import{a as G}from"./chunk-GS5TUS5R.js";import{n as N}from"./chunk-MZNFAKHZ.js";import"./chunk-74QUCIMR.js";import{$b as H,Kb as r,Lb as u,Ma as l,Mb as v,Nb as j,Ob as R,Zb as I,aa as U,db as x,eb as F,fa as w,fb as _,hb as S,kb as g,mb as B,nb as C,ob as z,pa as y,pb as i,qa as q,qb as n,rb as M,vb as L,ya as D,yb as E,zb as d}from"./chunk-APOJMTBA.js";import{a as O,b as k}from"./chunk-CWTPBX7D.js";var V=[["vector-spaces","Espacios vectoriales",0,["El vector cero","\xBFQu\xE9 vector contiene obligatoriamente todo subespacio vectorial, incluso el de dimensi\xF3n cero?","Todo subespacio contiene el producto de cualquiera de sus vectores por el escalar cero."],["Una combinaci\xF3n lineal","\xBFC\xF3mo se llama una suma de varios vectores multiplicados por escalares?","Escalar y sumar son las operaciones que forman el espacio generado."],["Una base","\xBFC\xF3mo se llama una familia linealmente independiente que adem\xE1s genera todo el espacio vectorial?","La independencia garantiza unicidad de coordenadas y la generaci\xF3n garantiza que existan."],["La dimensi\xF3n","En un espacio vectorial de dimensi\xF3n finita, \xBFqu\xE9 magnitud es igual al n\xFAmero de vectores de cualquier base?","Todas las bases de un mismo espacio de dimensi\xF3n finita tienen el mismo tama\xF1o."]],["dot-product","Producto escalar",0,["Son ortogonales","En el espacio eucl\xEDdeo, \xBFqu\xE9 relaci\xF3n tienen dos vectores no nulos cuyo producto escalar es cero?","El producto escalar es el producto de las normas por el coseno del \xE1ngulo."],["Es positivo","\xBFQu\xE9 signo tiene el producto escalar entre dos vectores no nulos si forman un \xE1ngulo estrictamente agudo?","El coseno de un \xE1ngulo agudo es positivo."],["El cuadrado de la norma","\xBFQu\xE9 cantidad se obtiene al calcular el producto escalar de un vector eucl\xEDdeo consigo mismo?","Se suman los cuadrados de todas sus coordenadas."],["Es negativo","\xBFQu\xE9 signo tiene u \xB7 v si u y v son vectores no nulos y v es un m\xFAltiplo negativo de u?","Se multiplica una norma al cuadrado positiva por un escalar negativo."]],["cross-product","Producto vectorial",0,["Un vector perpendicular a ambos","En tres dimensiones, \xBFqu\xE9 direcci\xF3n tiene el producto vectorial de dos vectores no paralelos?","Es perpendicular al plano que generan; el sentido se fija con la regla de la mano derecha."],["El \xE1rea del paralelogramo","\xBFQu\xE9 \xE1rea geom\xE9trica da la norma de u \xD7 v?","La norma es el producto de una base por la altura perpendicular a esa base."],["El vector cambia de signo","Si u \xD7 v \u2260 0, \xBFqu\xE9 le ocurre al producto vectorial al intercambiar los dos factores?","El producto vectorial es antisim\xE9trico."],["El vector cero","\xBFQu\xE9 da el producto vectorial de dos vectores paralelos?","No generan un paralelogramo con \xE1rea positiva."]],["scalar-triple-product","Producto mixto",1,["Un escalar","\xBFQu\xE9 tipo de resultado da u \xB7 (v \xD7 w) para tres vectores de \u211D\xB3?","El \xFAltimo operador es un producto escalar."],["El volumen del paralelep\xEDpedo","\xBFQu\xE9 mide el valor absoluto del producto mixto de tres vectores no coplanarios?","La norma del producto vectorial da el \xE1rea de la base y la proyecci\xF3n del tercero da la altura."],["Queda igual","\xBFQu\xE9 ocurre con un producto mixto no nulo al permutar c\xEDclicamente sus tres vectores?","Una permutaci\xF3n c\xEDclica de tres elementos equivale a dos intercambios, de modo que el signo se conserva."],["Cambia de signo","\xBFQu\xE9 le ocurre a un producto mixto no nulo si se intercambian solo dos de sus vectores?","La expresi\xF3n es un determinante y cambiar dos columnas invierte su signo."]],["matrix-determinant","Determinante de una matriz",1,["No es invertible","\xBFQu\xE9 se puede afirmar de una matriz cuadrada de determinante cero?","Al colapsar alguna direcci\xF3n, la transformaci\xF3n lineal no admite inversa."],["Cambia de signo","\xBFQu\xE9 ocurre con un determinante no nulo al intercambiar dos filas?","El determinante es alternante en sus filas."],["El producto de las entradas de la diagonal","En una matriz triangular superior, \xBFqu\xE9 expresi\xF3n da el determinante aunque haya entradas por encima de la diagonal?","Solo sobrevive el producto diagonal en la expansi\xF3n por permutaciones."],["El producto de los dos determinantes","Para dos matrices cuadradas A y B del mismo orden, \xBFc\xF3mo se obtiene det(AB) a partir de det(A) y det(B)?","Los factores orientados de escala se multiplican al componer transformaciones."]],["matrix-diagonalization","Diagonalizaci\xF3n de matrices",2,["Los autovectores de la base","En una diagonalizaci\xF3n A = PDP\u207B\xB9, \xBFqu\xE9 vectores forman las columnas de P?","Cada columna es un autovector y todas las columnas constituyen una base."],["Los autovalores correspondientes","En una diagonalizaci\xF3n A = PDP\u207B\xB9, \xBFqu\xE9 n\xFAmeros figuran en la diagonal de D?","Cada entrada diagonal es el autovalor del autovector situado en la columna correspondiente de P."],["La potencia de cada entrada diagonal","En A\u207F = PD\u207FP\u207B\xB9, \xBFc\xF3mo se calcula D\u207F si D es diagonal?","Cada coordenada se escala por su propia entrada diagonal n veces."],["No es diagonalizable sobre el mismo cuerpo","Si una matriz 3 \xD7 3 admite como m\xE1ximo dos autovectores linealmente independientes sobre \u211D, \xBFqu\xE9 falla al intentar diagonalizarla sobre \u211D?","Para formar una base de \u211D\xB3 hacen falta tres autovectores independientes."]],["gram-schmidt","Proceso de Gram\u2013Schmidt",2,["La proyecci\xF3n sobre las direcciones ya construidas","En Gram\u2013Schmidt, \xBFqu\xE9 se resta a un vector nuevo para hacerlo ortogonal a los anteriores?","Al quitar la componente en el subespacio anterior, queda solo la parte perpendicular."],["La norma del vector","Tras conseguir un vector ortogonal no nulo en Gram\u2013Schmidt, \xBFpor qu\xE9 cantidad se divide para normalizarlo?","Dividir por su norma produce longitud uno sin cambiar su direcci\xF3n."],["El subespacio generado no cambia","\xBFQu\xE9 ocurre con el subespacio que genera una familia independiente al ortonormalizarla con Gram\u2013Schmidt?","Cada vector nuevo se obtiene combinando el anterior con los ya procesados y viceversa."],["El residuo es cero","En Gram\u2013Schmidt, \xBFqu\xE9 sucede si un vector de entrada ya est\xE1 en el espacio generado por los anteriores?","Su proyecci\xF3n en ese espacio es el propio vector."]],["orthogonal-projections","Proyecciones ortogonales",2,["La componente perpendicular","Al proyectar ortogonalmente un vector sobre un subespacio, \xBFqu\xE9 parte del vector se elimina?","Solo se conserva la parte que pertenece al subespacio."],["El punto m\xE1s cercano del subespacio","\xBFQu\xE9 interpretaci\xF3n m\xE9trica tiene la proyecci\xF3n ortogonal de un punto sobre una recta?","Cualquier otro punto de la recta a\xF1ade un cateto no nulo al desplazamiento perpendicular."],["Queda igual en la segunda aplicaci\xF3n","\xBFQu\xE9 ocurre si aplicas dos veces seguidas la misma proyecci\xF3n ortogonal?","La primera imagen ya pertenece al subespacio y por tanto la segunda proyecci\xF3n la fija."],["El complemento ortogonal","\xBFQu\xE9 conjunto forma el n\xFAcleo de una proyecci\xF3n ortogonal sobre un subespacio W?","Se anulan exactamente los vectores perpendiculares a todo W."]],["cayley-hamilton","Teorema de Cayley\u2013Hamilton",2,["El polinomio caracter\xEDstico","\xBFQu\xE9 polinomio anula necesariamente a toda matriz cuadrada seg\xFAn Cayley\u2013Hamilton?","Al sustituir la variable del polinomio caracter\xEDstico por la matriz se obtiene la matriz nula."],["La matriz identidad","Al evaluar p(A) para aplicar Cayley\u2013Hamilton, \xBFpor qu\xE9 matriz se multiplica el t\xE9rmino constante de p?","El t\xE9rmino de grado cero es un escalar por A\u2070, y A\u2070 es la identidad."],["Divide al caracter\xEDstico","\xBFQu\xE9 relaci\xF3n cumple el polinomio m\xEDnimo respecto del polinomio caracter\xEDstico de la matriz?","El polinomio m\xEDnimo divide a todo polinomio que anule a la matriz."],["Una combinaci\xF3n de potencias de orden menor","Si A es 3 \xD7 3, \xBFc\xF3mo puede reescribirse A\xB3 gracias a Cayley\u2013Hamilton?","La relaci\xF3n m\xF3nica de grado tres despeja A\xB3 como combinaci\xF3n de A\xB2, A e I."]],["singular-values-operator-norms","Valores singulares y normas de operador",2,["Siempre son no negativos","\xBFQu\xE9 condici\xF3n de signo satisfacen los valores singulares de una matriz real?","Son ra\xEDces cuadradas de los autovalores de A\u1D40A, que es semidefinida positiva."],["El mayor valor singular","\xBFQu\xE9 cantidad da el m\xE1ximo factor de estiramiento de una matriz en norma eucl\xEDdea?","La norma de operador inducida por la norma eucl\xEDdea coincide con \u03C3\u2098\u2090\u2093."],["El n\xFAmero de valores singulares estrictamente positivos","\xBFC\xF3mo se obtiene el rango de una matriz a partir de sus valores singulares?","Los valores singulares no nulos corresponden a direcciones independientes que no colapsan."],["Puede tener m\xE1s columnas que filas","A diferencia de la diagonalizaci\xF3n ordinaria, \xBFqu\xE9 posibilidad admite una descomposici\xF3n en valores singulares para la forma de la matriz?","La SVD funciona tambi\xE9n para matrices rectangulares."]],["polynomial-interpolation","Interpolaci\xF3n polin\xF3mica",2,["Pasa por todos los puntos dados","\xBFQu\xE9 se exige a un polinomio interpolante para puntos con abscisas distintas?","En cada abscisa dada debe tomar exactamente la ordenada correspondiente."],["A lo sumo n \u2212 1","\xBFQu\xE9 cota de grado garantiza un interpolante \xFAnico para n puntos con abscisas distintas?","Se pueden combinar n polinomios cardinales de grado n \u2212 1."],["Tiene n ra\xEDces distintas","Para demostrar unicidad, \xBFqu\xE9 propiedad tiene la diferencia entre dos polinomios interpolantes para las mismas n abscisas?","La diferencia se anula en cada abscisa dada y un polinomio no nulo de grado menor que n no puede hacerlo."],["El error puede crecer cerca de los extremos","En el fen\xF3meno de Runge, \xBFqu\xE9 puede ocurrir al subir el grado con nodos equiespaciados?","La interpolaci\xF3n exacta en los nodos no impide oscilaciones grandes entre ellos."]],["binomial-theorem","Teorema del binomio",1,["Elegir en qu\xE9 factores aparece el segundo t\xE9rmino","Al desarrollar (x + y)\u207F, \xBFqu\xE9 cuenta el coeficiente de x\u207F\u207B\u1D4Fy\u1D4F?","Hay que decidir cu\xE1les de los n factores aportan una y."],["n + 1","\xBFCu\xE1ntos monomios distintos aparecen al desarrollar (x + y)\u207F con x e y indeterminadas y n entero no negativo?","El exponente de y toma todos los valores de 0 a n."],["2\u207F","\xBFQu\xE9 valor tiene la suma de todos los coeficientes del desarrollo de (x + y)\u207F?","Al sustituir x = y = 1, cada monomio vale uno y queda (1 + 1)\u207F."],["Cero","Para un entero n \u2265 1, \xBFcu\xE1nto vale la suma alternada de todos los coeficientes binomiales de orden n?","Se obtiene evaluando (1 \u2212 1)\u207F."]],["complex-arithmetic","Aritm\xE9tica compleja",1,["Cambiar el signo de la parte imaginaria","\xBFQu\xE9 operaci\xF3n produce el conjugado de a + bi?","La conjugaci\xF3n refleja el plano complejo en el eje real."],["El m\xF3dulo al cuadrado","\xBFQu\xE9 se obtiene al multiplicar un n\xFAmero complejo por su conjugado?","El producto (a + bi)(a \u2212 bi) vale a\xB2 + b\xB2."],["El producto de los m\xF3dulos","\xBFC\xF3mo se calcula el m\xF3dulo de zw a partir de los m\xF3dulos de z y w?","En la representaci\xF3n polar, las distancias al origen se multiplican."],["Un m\xFAltiplo del conjugado","Para z \u2260 0, \xBFc\xF3mo es el inverso 1/z en comparaci\xF3n con el conjugado de z?","Se divide el conjugado entre |z|\xB2, un escalar real positivo."]],["de-moivre","F\xF3rmula de De Moivre",1,["Se multiplica por n","\xBFQu\xE9 ocurre con el argumento polar al elevar un n\xFAmero complejo no nulo a la potencia entera positiva n?","Cada multiplicaci\xF3n suma el mismo \xE1ngulo; el resultado se entiende m\xF3dulo 2\u03C0."],["Se eleva a n","\xBFQu\xE9 ocurre con el m\xF3dulo al elevar un complejo a la potencia entera positiva n?","Los m\xF3dulos se multiplican n veces."],["Los v\xE9rtices de un pol\xEDgono regular centrado en el origen","\xBFQu\xE9 figura forman las n ra\xEDces n-\xE9simas de un n\xFAmero complejo no nulo para n \u2265 3?","Tienen el mismo m\xF3dulo y sus argumentos est\xE1n separados por 2\u03C0/n."],["Su separaci\xF3n angular es \u03C0/2","\xBFQu\xE9 separaci\xF3n angular tienen dos ra\xEDces cuartas consecutivas de un n\xFAmero complejo no nulo?","Cuatro argumentos uniformes reparten los 2\u03C0 radianes de una vuelta."]],["complex-logarithm-branches","Ramas del logaritmo complejo",2,["El argumento cambia en m\xFAltiplos de 2\u03C0","\xBFDe d\xF3nde sale la multiplicidad de valores del logaritmo de un complejo distinto de cero?","Argumentos que difieren en una vuelta dan el mismo punto del plano."],["El logaritmo real del m\xF3dulo","\xBFQu\xE9 parte real comparten todos los logaritmos de un mismo n\xFAmero complejo no nulo?","Si e\u02B7 = z, entonces e\u1D3F\u1D49\u207D\u02B7\u207E = |z|."],["Elegir un corte y una determinaci\xF3n continua del argumento","\xBFC\xF3mo se construye una rama holomorfa del logaritmo en un plano cortado a lo largo de una semirrecta desde cero?","Al impedir una vuelta completa alrededor del origen se puede elegir coherentemente el argumento."],["Aumenta en 2\u03C0i","Al continuar localmente el logaritmo una vuelta antihoraria alrededor de cero, \xBFc\xF3mo cambia el valor al regresar al punto inicial?","El argumento continuo aumenta en 2\u03C0 aunque el punto complejo sea el mismo."]],["rings-finite-fields","Anillos y cuerpos finitos",0,["Un inverso multiplicativo","En un cuerpo, \xBFqu\xE9 posee todo elemento distinto de cero?","Por eso se puede dividir por cualquier elemento no nulo."],["Es un cuerpo","\xBFQu\xE9 estructura tiene \u2124/p\u2124 con la suma y el producto usuales si p es primo?","Todos los residuos no nulos son coprimos con p y tienen inverso."],["Dos divisores de cero","Si n = ab con 1 < a, b < n, \xBFqu\xE9 son las clases de a y b en \u2124/n\u2124?","Ambas clases son no nulas, pero su producto es cero m\xF3dulo n."],["El elemento cero","En un cuerpo de caracter\xEDstica p, \xBFqu\xE9 se obtiene al sumar p copias del elemento unidad?","Por definici\xF3n de la caracter\xEDstica, p \xB7 1 = 0."]],["quaternions-rotations","Cuaterniones y rotaciones",2,["Un cuaterni\xF3n unitario","\xBFQu\xE9 tipo de cuaterni\xF3n codifica habitualmente una rotaci\xF3n espacial mediante conjugaci\xF3n?","La norma unitaria permite usar el conjugado como inverso."],["La mitad del \xE1ngulo de rotaci\xF3n","En q = cos \u03B1 + u sen \u03B1, con u un eje unitario, \xBFqu\xE9 representa \u03B1 respecto al giro espacial producido por q?","La acci\xF3n v \u21A6 qvq\u207B\xB9 produce un giro de \xE1ngulo 2\u03B1."],["Representan la misma rotaci\xF3n","\xBFQu\xE9 relaci\xF3n tienen las rotaciones espaciales representadas por los cuaterniones unitarios q y \u2212q?","Los dos cambios de signo se cancelan en la conjugaci\xF3n."],["El producto de los cuaterniones en el orden de composici\xF3n","\xBFC\xF3mo se combinan cuaterniones unitarios para representar dos rotaciones sucesivas?","La conjugaci\xF3n por el producto equivale a componer las dos conjugaciones y el orden importa."]]];var X=[["bolzano-theorem","Teorema de Bolzano",1,["La continuidad en todo el intervalo","\xBFQu\xE9 hip\xF3tesis sobre la funci\xF3n exige el teorema de Bolzano entre dos extremos de signos opuestos?","Un salto podr\xEDa saltarse el valor cero."],["Existe al menos una ra\xEDz interior","Si f es continua en [a,b] y f(a) < 0 < f(b), \xBFqu\xE9 garantiza Bolzano?","Continuidad y cambio de signo obligan a que la funci\xF3n cruce el nivel cero."],["La monoton\xEDa estricta","\xBFQu\xE9 hip\xF3tesis adicional garantiza que la ra\xEDz hallada con Bolzano sea \xFAnica?","Una funci\xF3n estrictamente mon\xF3tona toma cada valor como m\xE1ximo una vez."],["Puede haber una ra\xEDz a pesar del mismo signo en los extremos","En [\u22121,1], la funci\xF3n x\xB2 vale lo mismo y es positiva en ambos extremos. \xBFQu\xE9 ense\xF1a este ejemplo sobre la condici\xF3n de signos de Bolzano?","El cambio de signo es suficiente, pero una funci\xF3n puede tocar cero sin cruzarlo."]],["continuity-differentiability","Continuidad y derivabilidad",1,["Tiene que ser continua en ese punto","Si una funci\xF3n real es derivable en un punto, \xBFqu\xE9 se deduce sobre su continuidad all\xED?","El cociente incremental tiene l\xEDmite finito; al multiplicarlo por el incremento, la diferencia de valores tiende a cero."],["Los cocientes incrementales laterales tienen l\xEDmites distintos","\xBFPor qu\xE9 |x| no es derivable en cero a pesar de ser continua?","Los cocientes incrementales valen \u22121 por la izquierda y 1 por la derecha."],["Oscila sin l\xEDmite al acercarse a cero","Si f(0) = 0 y f(x) = x sen(1/x) para x \u2260 0, \xBFqu\xE9 comportamiento impide que exista f\u2032(0)?","El cociente incremental en cero se reduce a sen(1/x)."],["Tiende a cero","Para f(0) = 0 y f(x) = x\xB2 sen(1/x) si x \u2260 0, \xBFqu\xE9 hace el cociente incremental en cero?","El valor absoluto de x sen(1/x) est\xE1 acotado por |x|."]],["mean-value-theorems","Teoremas del valor medio",1,["La pendiente de la secante entre los extremos","En el teorema de Lagrange, \xBFqu\xE9 pendiente coincide con f\u2032(c) en alg\xFAn punto interior?","La derivada toma el valor del cociente (f(b) \u2212 f(a))/(b \u2212 a)."],["La derivada vale cero en alg\xFAn punto interior","\xBFQu\xE9 garantiza Rolle para una funci\xF3n continua en [a,b], derivable en (a,b) y con f(a) = f(b)?","La pendiente de la secante de extremos iguales es cero."],["La funci\xF3n es constante","Si la derivada de una funci\xF3n es cero en cada punto de un intervalo abierto, \xBFqu\xE9 implica el teorema del valor medio?","La diferencia de valores en cualquier par de puntos es la derivada de alg\xFAn punto intermedio por su separaci\xF3n."],["Una cota para el cambio de la funci\xF3n","Si |f\u2032| \u2264 M en un intervalo, \xBFqu\xE9 permite obtener el teorema del valor medio como M veces la distancia entre dos puntos?","La diferencia absoluta de valores queda acotada por M|b \u2212 a|."]],["global-extrema-weierstrass","Extremos de Weierstrass",0,["La continuidad de la funci\xF3n","Sobre un intervalo cerrado y acotado, \xBFqu\xE9 hip\xF3tesis de Weierstrass garantiza que una funci\xF3n real alcance m\xE1ximo y m\xEDnimo?","La imagen continua de un conjunto compacto es compacta."],["El supremo existe, pero no se alcanza","Para f(x) = x en el intervalo abierto (0,1), \xBFqu\xE9 conclusi\xF3n distingue supremo de m\xE1ximo?","El supremo es 1, pero el dominio excluye el punto que lo alcanzar\xEDa."],["Puede alcanzar su m\xE1ximo en un extremo","\xBFQu\xE9 puede ocurrir con el m\xE1ximo de una funci\xF3n derivable en el interior de [a,b] aunque su derivada nunca se anule all\xED?","La condici\xF3n de derivada cero solo se exige a extremos locales interiores."],["Un intervalo cerrado y acotado","En la versi\xF3n real del teorema de Weierstrass, \xBFqu\xE9 condici\xF3n sobre un intervalo no vac\xEDo equivale a su compacidad?","En la recta real, ser compacto equivale a ser cerrado y acotado."]],["convexity-tangents","Convexidad y tangentes",1,["Por debajo o sobre la cuerda","En la gr\xE1fica de una funci\xF3n convexa, \xBFd\xF3nde queda un punto intermedio con respecto al segmento entre dos puntos de la gr\xE1fica?","La definici\xF3n de convexidad compara f de un promedio con el promedio de los valores."],["Por encima o sobre la tangente","En una funci\xF3n convexa derivable, \xBFd\xF3nde queda la gr\xE1fica respecto a la tangente en un punto interior?","Cada tangente proporciona una cota inferior af\xEDn para la funci\xF3n."],["Es no decreciente","\xBFC\xF3mo cambia la derivada de una funci\xF3n convexa derivable al avanzar por su intervalo?","Las pendientes de las tangentes crecen o se mantienen."],["Todo m\xEDnimo local es global","\xBFQu\xE9 propiedad de optimizaci\xF3n se deduce de la convexidad en un intervalo?","Un punto de menor valor lejano crear\xEDa puntos de menor valor arbitrariamente cerca por interpolaci\xF3n convexa."]],["taylor-series","Series de Taylor",2,["El valor de la funci\xF3n en el centro","\xBFQu\xE9 da el t\xE9rmino constante del desarrollo de Taylor de f centrado en a?","El t\xE9rmino de orden cero es f(a)."],["La derivada de orden n dividida por n!","\xBFQu\xE9 coeficiente multiplica a (x \u2212 a)\u207F en la serie de Taylor?","Al derivar n veces ese monomio y evaluar en a aparece el factor n!."],["Ser infinitamente derivable no lo garantiza","\xBFQu\xE9 relaci\xF3n hay entre poseer derivadas de todos los \xF3rdenes y coincidir localmente con la propia serie de Taylor?","Hay funciones suaves cuyas derivadas en el centro son todas cero y que toman valores positivos arbitrariamente cerca."],["El radio de convergencia","En una serie de Taylor, \xBFqu\xE9 distancia al centro separa la zona de convergencia absoluta de la zona exterior de divergencia?","Fuera de ese radio la serie diverge; la frontera se estudia por separado."]],["lhopital-rule","Regla de L\u2019H\xF4pital",0,["El cociente de las derivadas","Una vez verificadas sus hip\xF3tesis, \xBFqu\xE9 cociente se estudia al aplicar L\u2019H\xF4pital a f(x)/g(x)?","La regla relaciona el l\xEDmite original con el de f\u2032(x)/g\u2032(x)."],["Una forma 0/0","Si numerador y denominador de un cociente tienden ambos a cero, \xBFqu\xE9 forma indeterminada aparece?","Los \xF3rdenes de anulaci\xF3n pueden producir l\xEDmites muy distintos."],["Una diferencia de infinitos","\xBFQu\xE9 forma indeterminada aparece si dos funciones positivas divergen a +\u221E y est\xE1s estudiando el l\xEDmite de su diferencia?","Antes de usar L\u2019H\xF4pital habr\xE1 que transformar la expresi\xF3n, por ejemplo en un cociente."],["Conviene usar continuidad y dividir directamente","Si en un cociente f(x)/g(x) ambos l\xEDmites son finitos y el del denominador no es cero, \xBFc\xF3mo se obtiene su l\xEDmite?","La divisi\xF3n es continua cuando el denominador es distinto de cero."]],["geometric-series","Series geom\xE9tricas",0,["La raz\xF3n com\xFAn","En una progresi\xF3n geom\xE9trica sin t\xE9rminos nulos, \xBFc\xF3mo se llama el factor fijo que lleva cada t\xE9rmino al siguiente?","La regla de la progresi\xF3n es multiplicar siempre por el mismo n\xFAmero."],["El valor absoluto de la raz\xF3n es menor que uno","Una serie geom\xE9trica tiene primer t\xE9rmino no nulo. \xBFQu\xE9 condici\xF3n sobre su raz\xF3n r garantiza convergencia?","Entonces r\u207F tiende a cero y las sumas parciales tienen l\xEDmite."],["Se resta la suma multiplicada por la raz\xF3n","\xBFQu\xE9 operaci\xF3n hace desaparecer los t\xE9rminos intermedios al deducir la suma finita de una progresi\xF3n geom\xE9trica?","En S \u2212 rS, cada t\xE9rmino interior aparece una vez con cada signo."],["Oscila entre dos valores","\xBFQu\xE9 hace la sucesi\xF3n de sumas parciales de la serie geom\xE9trica con primer t\xE9rmino 1 y raz\xF3n \u22121?","Al a\xF1adir alternadamente \u22121 y 1 se obtienen sumas 0 y 1 sin un \xFAnico l\xEDmite."]],["telescoping-series","Series telesc\xF3picas",1,["Los t\xE9rminos intermedios se cancelan","\xBFQu\xE9 rasgo distingue una suma telesc\xF3pica escrita como una cadena de diferencias consecutivas?","Cada t\xE9rmino interior aparece con ambos signos."],["a\u2081 \u2212 a\u2099\u208A\u2081","\xBFQu\xE9 queda al sumar a\u2096 \u2212 a\u2096\u208A\u2081 desde k = 1 hasta k = n?","Solo sobreviven el primer t\xE9rmino positivo y el \xFAltimo t\xE9rmino negativo."],["a\u2081 \u2212 L","Si a\u2099 tiende a L, \xBFcu\xE1nto vale la serie que suma a\u2096 \u2212 a\u2096\u208A\u2081 desde k = 1?","Se pasa al l\xEDmite en la expresi\xF3n de la suma parcial."],["La serie diverge","Si a\u2099 no tiene l\xEDmite real finito, \xBFqu\xE9 ocurre con la serie telesc\xF3pica de diferencias a\u2096 \u2212 a\u2096\u208A\u2081?","La suma parcial es una constante menos a\u2099\u208A\u2081, por lo que tampoco converge a un l\xEDmite finito."]],["positive-series-tests","Criterios para series positivas",1,["La comparaci\xF3n directa","Si 0 \u2264 a\u2099 \u2264 b\u2099 y \u03A3b\u2099 converge, \xBFqu\xE9 criterio permite concluir que \u03A3a\u2099 converge?","Las sumas parciales de \u03A3a\u2099 son crecientes y est\xE1n acotadas por la suma de \u03A3b\u2099."],["El criterio del cociente","\xBFQu\xE9 criterio para series de t\xE9rminos positivos estudia el l\xEDmite de a\u2099\u208A\u2081/a\u2099?","Un l\xEDmite menor que uno permite acotar la cola mediante una progresi\xF3n geom\xE9trica."],["El criterio integral","Si a\u2099 = f(n), con f positiva, continua y decreciente, \xBFqu\xE9 criterio relaciona \u03A3a\u2099 con el \xE1rea acumulada bajo f?","Las \xE1reas de los rect\xE1ngulos y de la regi\xF3n bajo la curva se acotan mutuamente."],["Los t\xE9rminos no tienden a cero","\xBFQu\xE9 hecho basta para descartar la convergencia de una serie sin aplicar ning\xFAn otro criterio?","La diferencia entre dos sumas parciales consecutivas deber\xEDa tender a cero."]],["squeeze-oscillation","Teorema del s\xE1ndwich y oscilaci\xF3n",2,["Las dos cotas tienen el mismo l\xEDmite","\xBFQu\xE9 condici\xF3n deben cumplir las cotas inferior y superior que encierran a una funci\xF3n para aplicar el teorema del s\xE1ndwich?","Si ambas se acercan al mismo valor, no dejan espacio para otro l\xEDmite."],["Acotar el valor absoluto por |x|","\xBFC\xF3mo se demuestra que x cos(1/x) tiende a cero cuando x tiende a cero, sin calcular el l\xEDmite de cos(1/x)?","El coseno est\xE1 entre \u22121 y 1, de modo que el producto queda entre \u2212|x| y |x|."],["Dos sucesiones dan dos l\xEDmites distintos","\xBFQu\xE9 tipo de argumento demuestra que sen(1/x) no tiene l\xEDmite al acercarse x a cero?","Se puede elegir una sucesi\xF3n que haga valer 1 al seno y otra que lo haga valer \u22121."],["La amplitud acaba anul\xE1ndose","\xBFPor qu\xE9 cos(n)/n converge aunque el factor cos(n) oscile?","La sucesi\xF3n est\xE1 encerrada entre \u22121/n y 1/n."]],["integration-numerical","Integraci\xF3n num\xE9rica",2,["Trapecios","En la regla del trapecio, \xBFcon qu\xE9 figuras se aproxima el \xE1rea bajo una gr\xE1fica positiva?","Se usa un segmento recto entre los valores de la funci\xF3n en cada par de nodos."],["Par\xE1bolas","En la interpretaci\xF3n interpolatoria de la regla de Simpson, \xBFqu\xE9 curvas aproximan la gr\xE1fica en bloques de tres nodos?","La f\xF3rmula integra en cada bloque un interpolante cuadr\xE1tico."],["Tiene que ser par","Para Simpson 1/3 compuesto en una malla uniforme, \xBFqu\xE9 restricci\xF3n cumple el n\xFAmero de subintervalos?","Cada aplicaci\xF3n elemental ocupa dos subintervalos."],["La integral de cualquier funci\xF3n c\xFAbica","\xBFQu\xE9 exactitud adicional tiene Simpson 1/3 en nodos equiespaciados, adem\xE1s de la exactitud para polinomios de grado hasta dos?","En un bloque sim\xE9trico, el t\xE9rmino c\xFAbico impar se cancela en la suma y en la integral."]],["jacobian-change-variables","Jacobiano y cambio de variables",2,["Escala local de \xE1rea o volumen","\xBFQu\xE9 representa geom\xE9tricamente el valor absoluto del determinante jacobiano en un cambio de coordenadas?","La derivada local aproxima la transformaci\xF3n por una aplicaci\xF3n lineal."],["r","En coordenadas polares x = r cos \u03B8 e y = r sen \u03B8, con r > 0, \xBFqu\xE9 factor jacobiano acompa\xF1a a dr d\u03B8?","Una variaci\xF3n angular a radio r tiene longitud aproximadamente r d\u03B8."],["Un posible colapso local de dimensiones","\xBFQu\xE9 indica un determinante jacobiano igual a cero acerca de la aproximaci\xF3n lineal en un punto?","La derivada no tiene rango completo y no es invertible como transformaci\xF3n lineal."],["Se ignora la orientaci\xF3n, pero no la escala","Al integrar una densidad con un cambio de variables que invierte la orientaci\xF3n, \xBFpor qu\xE9 aparece el m\xF3dulo del jacobiano?","El elemento de \xE1rea o volumen se mide con escala no negativa."]],["first-order-odes","Ecuaciones diferenciales de primer orden",2,["Un valor inicial de la funci\xF3n","\xBFQu\xE9 dato se a\xF1ade t\xEDpicamente a y\u2032 = f(x,y) para formular un problema de valor inicial de primer orden?","El dato fija el punto por donde debe pasar la trayectoria."],["Separaci\xF3n de variables","\xBFQu\xE9 t\xE9cnica se usa al escribir y\u2032 = g(x)h(y) como dy/h(y) = g(x) dx donde h(y) \u2260 0?","Cada lado queda en una sola variable y se integra por separado."],["Hay que comprobar las soluciones de equilibrio aparte","Antes de dividir por h(y) al separar variables en y\u2032 = g(x)h(y), \xBFqu\xE9 precauci\xF3n se toma si h tiene ceros?","Dividir puede eliminar una soluci\xF3n constante y(x) = c con h(c) = 0."],["Un factor integrante","En una ecuaci\xF3n lineal y\u2032 + p(x)y = q(x), \xBFqu\xE9 tipo de funci\xF3n permite convertir el lado izquierdo en una derivada de producto?","El factor \u03BC satisface \u03BC\u2032 = p\u03BC, de modo que (\u03BCy)\u2032 = \u03BC(y\u2032 + py)."]],["picard-lipschitz","Teorema de Picard\u2013Lindel\xF6f",2,["Un problema de valor inicial","\xBFA qu\xE9 problema aplica Picard\u2013Lindel\xF6f sus conclusiones de existencia y unicidad?","Se busca una trayectoria que satisfaga y\u2032 = f(t,y) y un dato y(t\u2080) = y\u2080."],["La condici\xF3n local de Lipschitz en la variable de estado","Adem\xE1s de continuidad, \xBFqu\xE9 regularidad en y usa Picard\u2013Lindel\xF6f para garantizar unicidad?","Acota cu\xE1nto puede variar f(t,y) al variar y, de manera uniforme localmente en t."],["La soluci\xF3n se garantiza en alg\xFAn intervalo alrededor del dato inicial","\xBFQu\xE9 significa que la existencia que garantiza Picard\u2013Lindel\xF6f sea local?","El teorema no afirma que la trayectoria contin\xFAe para todo tiempo."],["Pueden pasar varias trayectorias por el mismo dato inicial","En y\u2032 = \u221A|y| con y(0) = 0, \xBFqu\xE9 posibilidad ilustra la falta de Lipschitz cerca de y = 0?","Adem\xE1s de la soluci\xF3n nula, una soluci\xF3n puede quedarse en cero un tiempo y despegar despu\xE9s."]],["banach-fixed-point","Teorema del punto fijo de Banach",2,["Un punto que se env\xEDa a s\xED mismo","\xBFQu\xE9 es un punto fijo de una aplicaci\xF3n F?","En un punto fijo x se verifica F(x) = x."],["Una contracci\xF3n con constante menor que uno","\xBFQu\xE9 condici\xF3n de escala debe cumplir F para aplicar el teorema de Banach en un espacio m\xE9trico completo?","Las distancias entre im\xE1genes se multiplican a lo sumo por una constante estrictamente menor que uno."],["Como m\xE1ximo un punto fijo","Suponiendo solamente que F es una contracci\xF3n, aunque el espacio pueda ser incompleto, \xBFqu\xE9 se concluye sobre el n\xFAmero de puntos fijos?","Dos puntos fijos distintos deber\xEDan conservar su distancia, lo que contradice la contracci\xF3n."],["La completitud","\xBFQu\xE9 condici\xF3n del espacio permite asegurar que el l\xEDmite de la sucesi\xF3n de Cauchy generada por una contracci\xF3n sigue dentro del espacio?","Un espacio m\xE9trico completo contiene los l\xEDmites de todas sus sucesiones de Cauchy."]],["fourier-transform","Transformada de Fourier",2,["El contenido en frecuencias","\xBFQu\xE9 descripci\xF3n alternativa proporciona la transformada de Fourier de una se\xF1al en el tiempo?","Representa la se\xF1al mediante sus componentes oscilatorias."],["Una fase dependiente de la frecuencia","Al retrasar una se\xF1al sin deformarla, \xBFc\xF3mo cambia su transformada de Fourier bajo la convenci\xF3n con exponente negativo?","El retraso multiplica el espectro por una exponencial compleja de m\xF3dulo uno."],["El producto de las transformadas","Con la convenci\xF3n usual y para funciones integrables, \xBFen qu\xE9 se convierte una convoluci\xF3n temporal al aplicar la transformada de Fourier?","El cambio de variable en la integral separa los dos factores."],["Se ensancha en frecuencia","Si comprimes en el tiempo una se\xF1al gaussiana sin invertirla, \xBFqu\xE9 ocurre con la anchura de su transformada de Fourier?","La escala temporal y la escala de frecuencia var\xEDan inversamente."]]];var K=[["ellipse","La elipse",0,["La suma","En una elipse, \xBFqu\xE9 operaci\xF3n con las distancias de un punto de la curva a los dos focos da siempre 2a, siendo a el semieje mayor?","La elipse es el lugar de los puntos cuya suma de distancias a los focos es constante."],["El cociente","Si c es la distancia del centro de una elipse a un foco y a es el semieje mayor, \xBFqu\xE9 operaci\xF3n entre c y a da la excentricidad cuando c > 0?","La excentricidad es c/a, un valor menor que uno."],["La diferencia","Si una elipse de semiejes a \u2265 b > 0 tiene semiejes distintos, \xBFqu\xE9 operaci\xF3n entre a\xB2 y b\xB2 da el cuadrado de la distancia del centro a un foco?","El tri\xE1ngulo rect\xE1ngulo formado por el centro, un foco y un extremo del eje menor da c\xB2 = a\xB2 \u2212 b\xB2."],["El producto","\xBFQu\xE9 operaci\xF3n entre los semiejes de una elipse da su \xE1rea al multiplicar el resultado por \u03C0?","Escalar el c\xEDrculo unidad por a y b en dos direcciones perpendiculares multiplica el \xE1rea por ab."]],["parabola","La par\xE1bola",1,["La directriz","En la definici\xF3n geom\xE9trica de una par\xE1bola, \xBFc\xF3mo se llama la recta fija que se compara con el foco al medir distancias?","Cada punto de la par\xE1bola est\xE1 a igual distancia del foco y de esa recta."],["El v\xE9rtice","En una par\xE1bola, \xBFqu\xE9 punto queda a medio camino entre el foco y su proyecci\xF3n ortogonal sobre la directriz?","Ese punto se encuentra en el eje de simetr\xEDa y satisface la condici\xF3n de equidistancia."],["El eje de simetr\xEDa","En un reflector parab\xF3lico ideal, un rayo que parte del foco se refleja paralelo a una recta notable. \xBFA cu\xE1l?","La propiedad reflectora de la par\xE1bola relaciona el foco con la direcci\xF3n de su eje."],["El foco","En la ecuaci\xF3n y\xB2 = 4px, con p > 0, \xBFqu\xE9 elemento de la par\xE1bola se encuentra en (p, 0)?","Ese punto y la recta x = \u2212p dan las dos distancias iguales que definen la curva."]],["hyperbola","La hip\xE9rbola",0,["La diferencia absoluta de distancias a los focos","\xBFQu\xE9 cantidad vale lo mismo en todos los puntos de una hip\xE9rbola de dos ramas?","Al tomar el valor absoluto se obtiene la misma constante en las dos ramas."],["La excentricidad","En una hip\xE9rbola con semieje transversal a y distancia focal c desde el centro, \xBFqu\xE9 magnitud vale c/a y es mayor que uno?","La distancia al foco supera la distancia al v\xE9rtice, por lo que c/a > 1."],["La pendiente de una as\xEDntota","Para la hip\xE9rbola x\xB2/a\xB2 \u2212 y\xB2/b\xB2 = 1, con a y b positivos, \xBFqu\xE9 representa b/a?","Al igualar a cero la parte cuadr\xE1tica se obtienen las rectas y = \xB1(b/a)x."],["La longitud del eje transversal","Si los v\xE9rtices de una hip\xE9rbola centrada en el origen est\xE1n en (\u2212a, 0) y (a, 0), \xBFqu\xE9 mide 2a?","Los dos v\xE9rtices est\xE1n separados por dos veces la distancia de cada uno al centro."]],["circle-inversion","Inversi\xF3n en una circunferencia",2,["Queda fijo","En una inversi\xF3n de centro O y radio R, \xBFqu\xE9 le ocurre a un punto situado a distancia R de O?","Su distancia inversa es R\xB2/R = R y queda en la misma semirrecta."],["Se conserva la recta con el centro excluido","En el plano sin a\xF1adir un punto del infinito, \xBFqu\xE9 imagen tiene al invertirla una recta que pasa por el centro O, una vez excluido O?","La inversi\xF3n act\xFAa sobre ambas semirrectas y conserva la recta como conjunto con O excluido."],["Se transforma en una circunferencia que pasa por el centro","\xBFQu\xE9 imagen tiene una recta que no pasa por el centro de inversi\xF3n, si se completa su imagen con su punto l\xEDmite?","Los puntos de la recta se aproximan a O en la imagen cuando se alejan indefinidamente."],["Se transforma en una recta que no pasa por el centro","Al invertir una circunferencia que pasa por el centro O y excluir O antes de invertir, \xBFqu\xE9 conjunto se obtiene?","El paso por el centro es lo que convierte la circunferencia en una recta."]],["power-of-point","Potencia de un punto",2,["Cero","\xBFCu\xE1nto vale la potencia de un punto que pertenece a una circunferencia?","La potencia es OP\xB2 \u2212 R\xB2 y en la circunferencia se cumple OP = R."],["Un n\xFAmero negativo","\xBFCu\xE1l es el signo de la potencia de un punto estrictamente interior a una circunferencia?","La distancia al centro es menor que el radio."],["El cuadrado de la longitud de un segmento tangente","Desde un punto exterior P sale una tangente a una circunferencia y la toca en T. \xBFC\xF3mo se expresa la potencia positiva de P usando solo la longitud PT?","El radio OT es perpendicular a PT, as\xED que PT\xB2 = OP\xB2 \u2212 OT\xB2 por Pit\xE1goras."],["La diferencia de los cuadrados de la distancia al centro y del radio","\xBFQu\xE9 expresi\xF3n permite calcular la potencia de un punto que puede estar dentro, fuera o sobre una circunferencia?","La definici\xF3n OP\xB2 \u2212 R\xB2 funciona en las tres posiciones."]],["thales-theorem","El teorema de Tales",0,["Paralelas","En el teorema de Tales sobre proporcionalidad, \xBFc\xF3mo deben disponerse entre s\xED las rectas que cortan las dos transversales?","Las paralelas trasladan la misma escala de un lado al otro."],["Proporcionales","Varias rectas paralelas cortan dos transversales. Seg\xFAn el teorema de Tales, \xBFqu\xE9 relaci\xF3n tienen los segmentos correspondientes de ambas transversales?","La raz\xF3n entre dos intervalos correspondientes es constante."],["Semejantes","En un tri\xE1ngulo, una recta paralela a la base corta los otros dos lados. \xBFQu\xE9 relaci\xF3n hay entre el tri\xE1ngulo menor que comparte el v\xE9rtice y el tri\xE1ngulo completo?","La recta paralela conserva los \xE1ngulos correspondientes y, por tanto, la forma."],["Concurrentes","En la construcci\xF3n triangular usual del teorema de Tales, \xBFc\xF3mo se relacionan las rectas que contienen los dos lados cortados por las paralelas?","Las prolongaciones de esos lados se encuentran en el v\xE9rtice com\xFAn."]],["ceva-theorem","El teorema de Ceva",2,["El v\xE9rtice opuesto","En un tri\xE1ngulo, una ceviana une un punto de un lado con cierto punto del tri\xE1ngulo. \xBFCu\xE1l?","Una ceviana parte del v\xE9rtice que no pertenece al lado que corta."],["Un punto com\xFAn a las tres cevianas","En el teorema de Ceva, \xBFqu\xE9 significa que las tres cevianas interiores sean concurrentes?","Las tres rectas pasan por un mismo punto."],["El producto de las tres razones de avance por los lados","Con D en BC, E en CA y F en AB, todos interiores a sus lados, \xBFqu\xE9 se iguala a uno para comprobar la concurrencia de AD, BE y CF?","La condici\xF3n es (BD/DC)(CE/EA)(AF/FB) = 1."],["El punto medio del tercer lado","Si dos cevianas de un tri\xE1ngulo son medianas y una tercera pasa por su intersecci\xF3n, \xBFd\xF3nde corta esta tercera a su lado opuesto?","Las dos medianas dan razones 1; Ceva obliga a que la tercera raz\xF3n tambi\xE9n sea 1."]],["pythagorean-distance","Distancia pitag\xF3rica",0,["La hipotenusa","En la construcci\xF3n pitag\xF3rica de la distancia entre dos puntos del plano, los cambios horizontal y vertical son los catetos. \xBFQu\xE9 representa la distancia directa?","El segmento recto entre los puntos cierra el tri\xE1ngulo rect\xE1ngulo."],["La suma de los cuadrados de las diferencias de coordenadas","\xBFQu\xE9 expresi\xF3n da el cuadrado de la distancia eucl\xEDdea entre dos puntos del plano?","Pit\xE1goras suma los cuadrados de los desplazamientos ortogonales."],["El valor absoluto de la diferencia vertical","Si dos puntos distintos tienen la misma coordenada horizontal, \xBFa qu\xE9 se reduce su distancia eucl\xEDdea?","La diferencia horizontal es cero y la ra\xEDz del cuadrado restante da un valor absoluto."],["La distancia queda igual","Si se suma el mismo vector a dos puntos, \xBFqu\xE9 ocurre con la distancia pitag\xF3rica entre ellos?","La traslaci\xF3n se cancela al restar las coordenadas correspondientes."]],["homothety","Homotecias",1,["El centro de la homotecia","\xBFQu\xE9 punto queda fijo en una homotecia de raz\xF3n 2?","El desplazamiento del centro respecto a s\xED mismo es cero."],["El valor absoluto de la raz\xF3n","Para una homotecia de raz\xF3n negativa k, \xBFpor qu\xE9 factor se multiplican las longitudes?","El signo cambia el lado del centro donde queda la imagen; la longitud se escala por |k|."],["El cuadrado de la raz\xF3n","En una homotecia plana de raz\xF3n k \u2260 0, \xBFcu\xE1l es el factor por el que se multiplican las \xE1reas?","Como se escalan dos dimensiones, el factor es |k|\xB2 = k\xB2."],["El producto de las dos razones","Al componer dos homotecias del mismo centro, \xBFc\xF3mo se obtiene la raz\xF3n de la homotecia resultante?","Cada desplazamiento respecto al centro se multiplica una vez por cada raz\xF3n."]],["affine-transformations","Transformaciones afines",0,["La colinealidad de los puntos","Una cizalla transforma una cuadr\xEDcula rectangular en una oblicua. \xBFQu\xE9 relaci\xF3n se conserva para tres puntos originalmente alineados?","Una cizalla es una aplicaci\xF3n af\xEDn invertible y lleva rectas a rectas."],["Su punto medio","En una transformaci\xF3n af\xEDn invertible, \xBFa qu\xE9 punto del segmento imagen se env\xEDa el punto medio de un segmento original?","Las aplicaciones afines conservan combinaciones con coeficientes que suman uno."],["El valor absoluto del determinante de su parte lineal","En el plano, \xBFqu\xE9 factor multiplica el \xE1rea al aplicar una transformaci\xF3n af\xEDn invertible?","La traslaci\xF3n no cambia el \xE1rea; la parte lineal escala \xE1reas por el m\xF3dulo de su determinante."],["El vector de traslaci\xF3n","Para una aplicaci\xF3n af\xEDn escrita F(x) = Ax + b, \xBFqu\xE9 devuelve F(0)?","El producto A0 es cero, por eso la imagen del origen es b."]],["convex-hull","Envolvente convexa",0,["El segmento que los une","\xBFQu\xE9 debe contener un conjunto convexo junto con dos puntos cualesquiera del conjunto?","La convexidad exige contener todas las combinaciones convexas de esos dos puntos."],["El menor conjunto convexo que contiene los puntos","\xBFQu\xE9 representa la envolvente convexa de una nube finita de puntos?","Es la intersecci\xF3n de todos los conjuntos convexos que contienen la nube."],["Un pol\xEDgono con v\xE9rtices tomados de la nube","Cuando una nube finita del plano contiene tres puntos no alineados, \xBFqu\xE9 forma tiene su envolvente convexa?","El casco tiene interior y sus v\xE9rtices son puntos extremos de la nube."],["La envolvente queda igual","Si se a\xF1ade un punto estrictamente interior a una envolvente convexa plana, \xBFqu\xE9 ocurre al recalcular la envolvente?","Los cascos antes y despu\xE9s de a\xF1adirlo se contienen mutuamente."]],["shoelace-formula","F\xF3rmula del cord\xF3n",2,["Los v\xE9rtices en el orden del contorno","\xBFQu\xE9 datos necesita la f\xF3rmula del cord\xF3n para hallar el \xE1rea de un pol\xEDgono simple?","Los productos cruzados se forman con coordenadas consecutivas, incluyendo el cierre del contorno."],["El signo del \xE1rea orientada","Si inviertes el sentido de recorrido del contorno en la f\xF3rmula del cord\xF3n, \xBFqu\xE9 cambia en el \xE1rea orientada?","Cada producto cruzado cambia de signo al invertir el orden de sus puntos."],["La mitad del valor absoluto de la suma de productos cruzados con signo","\xBFC\xF3mo se obtiene un \xE1rea geom\xE9trica no negativa con la f\xF3rmula del cord\xF3n?","La suma orientada viene duplicada por la f\xF3rmula y su signo solo indica el sentido del recorrido."],["El \xE1rea orientada queda igual","En la f\xF3rmula del cord\xF3n, \xBFqu\xE9 ocurre con el \xE1rea orientada si recorres el mismo pol\xEDgono en el mismo sentido empezando en otro v\xE9rtice?","Se hace una permutaci\xF3n c\xEDclica de los mismos sumandos."]],["ptolemy-theorem","Teorema de Ptolomeo",0,["Ambas diagonales","En el teorema de Ptolomeo para un cuadril\xE1tero c\xEDclico, \xBFqu\xE9 dos segmentos se multiplican en el lado izquierdo de AC \xB7 BD = AB \xB7 CD + BC \xB7 DA?","AC y BD unen pares de v\xE9rtices opuestos."],["La suma de los productos de lados opuestos","Seg\xFAn Ptolomeo, \xBFqu\xE9 cantidad iguala al producto de las diagonales de un cuadril\xE1tero inscrito en una circunferencia?","Las dos parejas de lados opuestos aportan un producto cada una."],["La igualdad de Pit\xE1goras","Al aplicar Ptolomeo a un rect\xE1ngulo de lados a y b y diagonales d, \xBFqu\xE9 igualdad geom\xE9trica se recupera?","Las dos diagonales tienen longitud d y los productos de lados opuestos valen a\xB2 y b\xB2."],["Una misma circunferencia","\xBFQu\xE9 lugar geom\xE9trico comparten los cuatro v\xE9rtices de un cuadril\xE1tero c\xEDclico al que aplicamos el teorema de Ptolomeo?","La condici\xF3n de ser c\xEDclico significa que los cuatro v\xE9rtices est\xE1n en un mismo c\xEDrculo."]],["nine-point-circle","Circunferencia de los nueve puntos",2,["Los puntos medios de los lados","En la circunferencia de los nueve puntos de un tri\xE1ngulo no degenerado, \xBFqu\xE9 tres puntos se obtienen bisecando cada lado?","El tri\xE1ngulo medial tiene sus tres v\xE9rtices sobre esa circunferencia."],["Los pies de las alturas","\xBFC\xF3mo se llaman los tres puntos de la circunferencia de los nueve puntos donde cada altura corta la recta de su lado opuesto?","La proyecci\xF3n perpendicular de cada v\xE9rtice sobre la recta opuesta da el pie de su altura."],["El punto medio entre el circuncentro y el ortocentro","En un tri\xE1ngulo no equil\xE1tero, \xBFd\xF3nde est\xE1 el centro de la circunferencia de los nueve puntos sobre la recta de Euler?","La homotecia de centro ortocentro y raz\xF3n 1/2 lleva el circuncentro al centro buscado."],["Los puntos medios entre cada v\xE9rtice y el ortocentro","\xBFQu\xE9 tres puntos de la circunferencia de los nueve puntos proceden de los segmentos que unen cada v\xE9rtice con el ortocentro?","La homotecia de centro ortocentro y raz\xF3n 1/2 env\xEDa cada v\xE9rtice a uno de esos puntos."]],["polyhedral-duality","Dualidad de poliedros",0,["Los v\xE9rtices del dual","En la dualidad combinatoria de poliedros, \xBFqu\xE9 corresponden a las caras del poliedro original?","Cada cara original da lugar a un v\xE9rtice y las incidencias se invierten."],["Las caras del dual","En la dualidad de poliedros, \xBFqu\xE9 representan en el dual los v\xE9rtices del poliedro original?","Las caras duales agrupan v\xE9rtices duales procedentes de las caras incidentes en cada v\xE9rtice original."],["Un octaedro","\xBFQu\xE9 s\xF3lido plat\xF3nico es el dual del cubo?","El cubo tiene seis caras y ocho v\xE9rtices; el octaedro intercambia esas cantidades."],["Una arista del dual","En la dualidad de un poliedro convexo, \xBFqu\xE9 elemento dual corresponde a la arista que separa dos caras originales?","La arista dual une los v\xE9rtices que representan esas dos caras."]],["sine-law","La ley de los senos",2,["El seno del \xE1ngulo opuesto","En un tri\xE1ngulo con lados a, b y c, seg\xFAn la ley de los senos, \xBFqu\xE9 funci\xF3n del \xE1ngulo corresponde al lado a en el cociente constante?","Cada lado se divide por el seno del \xE1ngulo situado frente a \xE9l."],["El di\xE1metro de la circunferencia circunscrita","En la ley extendida de los senos, \xBFqu\xE9 longitud com\xFAn vale a/sen A para un tri\xE1ngulo con A opuesto a a?","La cuerda a mide 2R sen A, donde R es el radio circunscrito."],["Un segundo \xE1ngulo suplementario","Al resolver un tri\xE1ngulo con la ley de los senos, hallas un \xE1ngulo agudo a partir de un seno entre 0 y 1. \xBFQu\xE9 otro \xE1ngulo tiene el mismo seno y debe comprobarse?","Los \xE1ngulos B y 180\xB0 \u2212 B tienen el mismo seno, aunque solo algunos datos admiten ambos tri\xE1ngulos."],["La igualdad de los lados","En un tri\xE1ngulo con dos \xE1ngulos iguales, \xBFqu\xE9 concluyes sobre sus lados opuestos usando la ley de los senos?","El cociente com\xFAn y los senos iguales fuerzan que las longitudes coincidan."]],["law-of-cosines","La ley de los cosenos",2,["El \xE1ngulo comprendido entre los dos lados conocidos","Para hallar un tercer lado con la ley de los cosenos a partir de dos longitudes, \xBFqu\xE9 \xE1ngulo se usa?","El coseno que entra en la f\xF3rmula corresponde al \xE1ngulo opuesto al lado buscado."],["La relaci\xF3n de Pit\xE1goras","Cuando el \xE1ngulo comprendido es recto, \xBFen qu\xE9 se convierte la ley de los cosenos?","Al ser cero el coseno, desaparece el t\xE9rmino cruzado."],["Un \xE1ngulo obtuso","En un tri\xE1ngulo, el cuadrado de un lado supera la suma de los cuadrados de los otros dos. \xBFQu\xE9 tipo de \xE1ngulo hay frente a ese lado?","La ley de los cosenos obliga a que el coseno de ese \xE1ngulo sea negativo."],["Un \xE1ngulo agudo","Seg\xFAn la ley de los cosenos, si c\xB2 < a\xB2 + b\xB2 en un tri\xE1ngulo, \xBFqu\xE9 tipo de \xE1ngulo se abre entre los lados a y b?","El coseno es positivo porque (a\xB2 + b\xB2 \u2212 c\xB2)/(2ab) es positivo."]],["plane-tessellations","Teselaciones del plano",0,["Tri\xE1ngulos equil\xE1teros","\xBFCon qu\xE9 pol\xEDgonos regulares congruentes se obtiene una teselaci\xF3n del plano con seis pol\xEDgonos en cada v\xE9rtice?","Cada \xE1ngulo mide 60\xB0, por lo que seis de ellos completan una vuelta."],["Cuadrados","\xBFCon qu\xE9 pol\xEDgonos regulares congruentes se obtiene una teselaci\xF3n del plano que re\xFAne cuatro \xE1ngulos rectos en cada v\xE9rtice?","Cuatro \xE1ngulos de 90\xB0 completan los 360\xB0 alrededor del v\xE9rtice."],["Hex\xE1gonos regulares","En una teselaci\xF3n regular del plano, \xBFqu\xE9 pol\xEDgonos pueden reunirse de tres en tres con \xE1ngulos interiores de 120\xB0?","Tres \xE1ngulos de 120\xB0 completan una vuelta sin huecos ni solapamientos."],["Pent\xE1gonos regulares","\xBFCu\xE1l de estos pol\xEDgonos regulares no puede teselar el plano por s\xED solo con uniones de arista a arista?","Su \xE1ngulo interior es 108\xB0, que no divide exactamente los 360\xB0 de un v\xE9rtice."]]];var Y=[["modular-arithmetic","Aritm\xE9tica modular",0,["Tienen el mismo resto","Si dos enteros son congruentes m\xF3dulo 7, \xBFc\xF3mo se comparan los restos de dividirlos por 7?","Cada entero deja el mismo resto est\xE1ndar al dividirlo por 7."],["Su diferencia es m\xFAltiplo del m\xF3dulo","Si a \u2261 b m\xF3dulo m, \xBFqu\xE9 asegura la definici\xF3n de congruencia sobre a \u2212 b?","Existe un entero k tal que a \u2212 b = km."],["Se puede cancelar en la congruencia","Si da \u2261 db m\xF3dulo m y d es coprimo con m, \xBFqu\xE9 se puede hacer con el factor d?","d tiene inverso m\xF3dulo m y se puede multiplicar por \xE9l a ambos lados."],["El resto vuelve a empezar en cero","En el ciclo de restos m\xF3dulo m, \xBFqu\xE9 sucede al sumar uno al resto m \u2212 1?","El entero m pertenece a la clase de cero."]],["gcd-euclid","Algoritmo de Euclides",0,["El \xFAltimo resto no nulo","Al aplicar el algoritmo de Euclides a dos enteros positivos, \xBFqu\xE9 entrada de la lista de restos da el m\xE1ximo com\xFAn divisor?","La siguiente divisi\xF3n da resto cero; el divisor de ese paso es el \xFAltimo resto no nulo, contando los datos iniciales."],["El divisor pasa a ser el dividendo y el resto pasa a ser el divisor","En una divisi\xF3n con resto positivo del algoritmo de Euclides, \xBFc\xF3mo se contin\xFAa?","El divisor y el resto tienen exactamente los mismos divisores comunes que el par original."],["El m\xE1ximo com\xFAn divisor es el divisor de ese paso","En el algoritmo de Euclides, \xBFqu\xE9 concluyes si el resto de la divisi\xF3n actual es cero?","El divisor divide al dividendo, por lo que es su mayor divisor com\xFAn."],["El m\xE1ximo com\xFAn divisor es uno","Si en el algoritmo de Euclides aparece un resto igual a 1, \xBFqu\xE9 sabes de los enteros iniciales?","La siguiente divisi\xF3n ser\xE1 exacta y 1 ser\xE1 el \xFAltimo resto no nulo."]],["chinese-remainder-theorem","Teorema chino del resto",2,["M\xF3dulos coprimos por parejas","\xBFQu\xE9 hip\xF3tesis del teorema chino del resto garantiza una soluci\xF3n para cualesquiera residuos prescritos?","Los m\xF3dulos coprimos por parejas permiten combinar las condiciones sin conflictos."],["El producto de los m\xF3dulos","Si los m\xF3dulos son coprimos por parejas, \xBFrespecto a qu\xE9 m\xF3dulo es \xFAnica la soluci\xF3n del teorema chino del resto?","La diferencia entre dos soluciones es m\xFAltiplo de todos los m\xF3dulos y, por coprimalidad, de su producto."],["El m\xE1ximo com\xFAn divisor de los dos m\xF3dulos","Con dos m\xF3dulos no coprimos, \xBFqu\xE9 debe dividir la diferencia entre los residuos para que el sistema sea compatible?","Las dos congruencias fuerzan la misma clase m\xF3dulo el divisor com\xFAn y esta condici\xF3n es suficiente."],["El m\xEDnimo com\xFAn m\xFAltiplo de los m\xF3dulos","Para dos m\xF3dulos compatibles que comparten alg\xFAn factor, \xBFcu\xE1l es el menor periodo positivo de las soluciones?","La diferencia entre dos soluciones debe ser m\xFAltiplo de ambos m\xF3dulos, y basta con eso."]],["euler-totient-formula","Funci\xF3n \u03C6 de Euler",1,["Los residuos coprimos con n","\xBFQu\xE9 cuenta \u03C6(n) para un entero n > 1?","Son las clases que tienen inverso m\xF3dulo n."],["p \u2212 1","Para un primo p, \xBFcu\xE1nto vale \u03C6(p)?","Las clases 1 a p \u2212 1 son todas coprimas con p."],["p\u1D4F \u2212 p\u1D4F\u207B\xB9","Para un primo p y un entero k \u2265 2, \xBFcu\xE1nto vale \u03C6(p\u1D4F)?","Hay que excluir los p\u1D4F\u207B\xB9 residuos que son m\xFAltiplos de p."],["\u03C6(a) \xB7 \u03C6(b)","Si a y b son coprimos, \xBFc\xF3mo se expresa \u03C6(ab) mediante sus dos totientes?","El teorema chino del resto empareja los residuos invertibles m\xF3dulo ab con pares de residuos invertibles."]],["fermats-little-theorem","Peque\xF1o teorema de Fermat",2,["a\u1D56 \u2261 a m\xF3dulo p","\xBFQu\xE9 congruencia da el peque\xF1o teorema de Fermat para todo entero a y todo primo p?","Esta formulaci\xF3n incluye los m\xFAltiplos de p, caso en el que ambos miembros son cero m\xF3dulo p."],["a\u1D56\u207B\xB9 \u2261 1 m\xF3dulo p","Con p primo y a no divisible por p, \xBFqu\xE9 congruencia se obtiene al cancelar un factor a a ambos lados de a\u1D56 \u2261 a m\xF3dulo p?","Como a es invertible m\xF3dulo p, dividir ambos miembros por a es v\xE1lido."],["a\u1D56\u207B\xB2","Con p primo y a coprimo con p, \xBFqu\xE9 potencia proporciona, en general, un inverso de a m\xF3dulo p?","Multiplicar por a da a\u1D56\u207B\xB9, congruente con uno."],["Certificar que el m\xF3dulo es compuesto","Si un entero n > 1 y una base a incumplen a\u207F \u2261 a m\xF3dulo n, \xBFqu\xE9 permite concluir este fallo en una prueba de Fermat?","Todos los primos satisfacen la congruencia; un contraejemplo descarta la primalidad."]],["sieve-primality","Criba y primalidad",1,["La criba de Erat\xF3stenes","\xBFQu\xE9 m\xE9todo obtiene la lista de primos hasta una cota tachando m\xFAltiplos de cada primo descubierto?","Los \xEDndices sin tachar al final corresponden a los primos."],["La ra\xEDz cuadrada del candidato","Para decidir por divisiones si un entero es primo, \xBFhasta qu\xE9 cota basta buscar un divisor primo?","En un producto de dos factores, al menos uno es menor o igual que la ra\xEDz del producto."],["El cuadrado del primo que estamos procesando","En la criba de Erat\xF3stenes, \xBFdesde qu\xE9 m\xFAltiplo de un primo p se puede empezar a tachar sin dejar compuestos sin marcar?","Cada m\xFAltiplo de p menor que p\xB2 tiene un factor menor que p y ya se marc\xF3."],["Una lista muy grande de enteros por marcar","\xBFQu\xE9 consume memoria en una criba directa hasta N, frente a una prueba de primalidad de un solo candidato?","La criba directa guarda una marca para cada candidato del intervalo."]],["fundamental-theorem-arithmetic","Teorema fundamental de la aritm\xE9tica",1,["Producto de primos","\xBFC\xF3mo se puede escribir todo entero mayor que 1 seg\xFAn el teorema fundamental de la aritm\xE9tica?","Se descompone en factores primos, que pueden repetirse."],["Solo el orden de los factores","\xBFQu\xE9 puede cambiar entre dos factorizaciones primas del mismo entero positivo mayor que 1?","Los mismos primos aparecen con las mismas multiplicidades."],["El menor exponente de cada primo","Al construir el m\xE1ximo com\xFAn divisor a partir de dos factorizaciones primas, \xBFqu\xE9 exponente se asigna a cada primo?","El divisor que buscamos debe dividir a ambos n\xFAmeros y usar el mayor exponente que ambos permiten."],["El mayor exponente de cada primo","Al construir el m\xEDnimo com\xFAn m\xFAltiplo a partir de dos factorizaciones primas, \xBFqu\xE9 exponente se asigna a cada primo?","El m\xFAltiplo buscado necesita al menos los exponentes de los dos n\xFAmeros y no requiere m\xE1s."]],["factorials-legendre","F\xF3rmula de Legendre para factoriales",2,["El exponente de la mayor potencia de p que divide a n!","\xBFQu\xE9 mide la valoraci\xF3n p-\xE1dica de n! cuando p es primo?","Es el exponente del factor p en la factorizaci\xF3n prima de n!."],["La cantidad de m\xFAltiplos de p hasta n","En la f\xF3rmula de Legendre para n!, \xBFqu\xE9 cuenta el primer sumando \u230An/p\u230B?","Cada m\xFAltiplo de p aporta por lo menos una copia del factor p."],["Un aporte adicional por cada m\xFAltiplo de p\xB2","\xBFPor qu\xE9 la f\xF3rmula de Legendre a\xF1ade \u230An/p\xB2\u230B despu\xE9s de contar m\xFAltiplos de p?","Los m\xFAltiplos de p\xB2 aportan una segunda copia del factor p."],["La valoraci\xF3n respecto de 5","\xBFQu\xE9 basta calcular para contar los ceros finales de n! en base diez?","Cada cero exige un 2 y un 5, y en un factorial nunca hay menos doses que cincos."]],["continued-fractions","Fracciones continuas",2,["Termina tras un n\xFAmero finito de pasos","\xBFQu\xE9 ocurre con la fracci\xF3n continua simple de un n\xFAmero racional si se obtiene con divisiones eucl\xEDdeas?","Los restos del algoritmo de Euclides disminuyen hasta llegar a cero."],["Se corta la expresi\xF3n tras un t\xE9rmino","\xBFC\xF3mo se obtiene un convergente de una fracci\xF3n continua infinita?","Al quedarse con un prefijo finito se obtiene una fracci\xF3n racional que aproxima el valor."],["Es eventualmente peri\xF3dica","\xBFQu\xE9 patr\xF3n caracteriza a la fracci\xF3n continua simple de un irracional cuadr\xE1tico?","El teorema de Lagrange hace equivalentes la periodicidad eventual y ser un irracional cuadr\xE1tico."],["Son coprimos","\xBFQu\xE9 relaci\xF3n guardan numerador y denominador de cada convergente calculado con las recurrencias usuales?","La diferencia de productos cruzados con el convergente anterior es \xB11."]],["fibonacci-numbers","N\xFAmeros de Fibonacci",0,["La suma de los dos t\xE9rminos anteriores","\xBFQu\xE9 regla determina cada nuevo n\xFAmero de la sucesi\xF3n de Fibonacci?","La recurrencia usa la suma de los dos valores previos."],["La raz\xF3n \xE1urea","\xBFA qu\xE9 valor tiende el cociente F\u2099\u208A\u2081/F\u2099 de n\xFAmeros de Fibonacci consecutivos?","El valor l\xEDmite positivo satisface x = 1 + 1/x."],["El m\xE1ximo com\xFAn divisor vale uno","\xBFQu\xE9 relaci\xF3n aritm\xE9tica tienen dos t\xE9rminos consecutivos positivos de Fibonacci?","Aplicar repetidamente el algoritmo de Euclides reduce el par a los t\xE9rminos iniciales 1 y 1."],["Los valores de los dos primeros t\xE9rminos","Si conoces la recurrencia de Fibonacci pero quieres distinguir esa sucesi\xF3n de otras con la misma regla, \xBFqu\xE9 datos iniciales necesitas fijar?","Una recurrencia de orden dos requiere dos valores iniciales para determinar los siguientes."]],["perfect-numbers","N\xFAmeros perfectos",0,["Perfecto","Los divisores propios de 28 son 1, 2, 4, 7 y 14, y suman 28. \xBFQu\xE9 clase de n\xFAmero es seg\xFAn esta suma?","Un n\xFAmero es perfecto cuando la suma de sus divisores propios coincide con \xE9l."],["Deficiente","\xBFC\xF3mo se clasifica un entero positivo si la suma de sus divisores propios es menor que \xE9l?","Por ejemplo, todo primo p tiene como \xFAnico divisor propio 1 y 1 < p."],["Abundante","\xBFC\xF3mo se clasifica un entero n si al sumar todos sus divisores, incluido n, se obtiene m\xE1s que 2n?","Al quitar n de los dos lados queda una suma de divisores propios superior a n."],["Divisores propios","Al comprobar si un n\xFAmero es perfecto con la definici\xF3n m\xE1s habitual, \xBFqu\xE9 divisores se suman?","Se incluyen todos los divisores positivos excepto el propio n\xFAmero."]],["sum-of-two-squares","Suma de dos cuadrados",0,["Los primos congruentes con 1 m\xF3dulo 4","\xBFQu\xE9 primos impares se pueden escribir como suma de dos cuadrados de enteros?","El teorema de los dos cuadrados caracteriza as\xED a todos los primos impares representables."],["Los primos congruentes con 3 m\xF3dulo 4","\xBFA qu\xE9 primos se aplica la condici\xF3n de tener exponente par en la factorizaci\xF3n para que un entero positivo sea suma de dos cuadrados?","La caracterizaci\xF3n de las sumas de dos cuadrados obliga a que esos factores aparezcan por parejas."],["El producto sigue siendo suma de dos cuadrados","Si dos enteros son suma de dos cuadrados, \xBFqu\xE9 garantiza la identidad que multiplica normas de n\xFAmeros complejos?","El producto de (a + bi) y (c + di) tiene norma igual al producto de las normas originales."],["El primo 2","\xBFQu\xE9 primo queda fuera de las clases impares m\xF3dulo 4 y se escribe como 1\xB2 + 1\xB2?","El n\xFAmero 2 es el \xFAnico primo par."]],["collatz","Conjetura de Collatz",0,["Dividir por 2","En la iteraci\xF3n de Collatz, \xBFqu\xE9 operaci\xF3n se aplica a un entero positivo par?","La rama par reemplaza n por n/2."],["Multiplicar por 3 y sumar 1","En la iteraci\xF3n de Collatz, \xBFqu\xE9 operaci\xF3n se aplica a un entero positivo impar?","La rama impar produce 3n + 1, que siempre es par."],["Un ciclo distinto de 1 \u2192 4 \u2192 2 \u2192 1","\xBFQu\xE9 hallazgo en una trayectoria de enteros positivos refutar\xEDa la conjetura de Collatz aunque todos sus valores fueran acotados?","Una trayectoria atrapada en otro ciclo nunca alcanzar\xEDa 1."],["Una comprobaci\xF3n para muchos valores iniciales","\xBFQu\xE9 tipo de evidencia proporciona ejecutar la iteraci\xF3n de Collatz hasta 1 para un conjunto finito de semillas?","Solo quedan resueltas las trayectorias comprobadas y las que enlacen con ellas."]],["pell-equation","Ecuaci\xF3n de Pell",2,["x\xB2 \u2212 Dy\xB2 = 1","\xBFCu\xE1l es la forma cl\xE1sica de la ecuaci\xF3n de Pell para un entero positivo D que no es cuadrado?","La diferencia fija entre los dos t\xE9rminos es uno."],["La fracci\xF3n continua de \u221AD","\xBFQu\xE9 expansi\xF3n permite encontrar soluciones enteras de la ecuaci\xF3n de Pell?","La periodicidad de la ra\xEDz cuadrada conecta sus convergentes con la ecuaci\xF3n."],["Potencias de una soluci\xF3n fundamental","Una vez obtenida la soluci\xF3n fundamental positiva de Pell, \xBFc\xF3mo se generan otras soluciones positivas mediante el n\xFAmero x + y\u221AD?","La norma x\xB2 \u2212 Dy\xB2 se multiplica, por lo que permanece igual a uno al elevar a potencias."],["Solo quedan soluciones con y = 0","Si D es un cuadrado positivo m\xB2, \xBFqu\xE9 ocurre con las soluciones enteras de x\xB2 \u2212 Dy\xB2 = 1?","Los enteros x \u2212 my y x + my tienen producto uno, as\xED que ambos son 1 o ambos son \u22121."]],["frobenius-coins","Problema de las monedas de Frobenius",0,["Usar cantidades enteras no negativas de monedas","En el problema de Frobenius, \xBFqu\xE9 restricci\xF3n se impone a los coeficientes de las denominaciones al representar un importe?","Se permiten cero o m\xE1s monedas de cada tipo, sin restar monedas."],["Ser m\xFAltiplo del divisor com\xFAn","Si dos denominaciones comparten un divisor d > 1, \xBFqu\xE9 condici\xF3n necesaria cumple todo importe alcanzable?","Cada suma de denominaciones es m\xFAltiplo de d."],["ab \u2212 a \u2212 b","Para dos denominaciones coprimas a, b > 1, \xBFcu\xE1l es el mayor importe imposible de representar?","El resultado de Frobenius para dos denominaciones es ab \u2212 a \u2212 b."],["Todos los importes se pueden representar","\xBFQu\xE9 ocurre con los importes enteros no negativos si una de las denominaciones es 1?","Basta usar el n\xFAmero necesario de monedas de valor 1."]],["rational-root-theorem","Teorema de la ra\xEDz racional",0,["El t\xE9rmino independiente","Si p/q en t\xE9rminos reducidos es ra\xEDz de un polinomio con coeficientes enteros y t\xE9rmino independiente no nulo, \xBFqu\xE9 coeficiente debe ser m\xFAltiplo de p?","Al eliminar denominadores en la ecuaci\xF3n, el t\xE9rmino independiente queda forzado a ser divisible por p."],["El coeficiente principal","Si p/q en t\xE9rminos reducidos es ra\xEDz racional de un polinomio entero, \xBFqu\xE9 coeficiente debe ser m\xFAltiplo de q?","La coprimalidad entre p y q fuerza que el denominador divida al coeficiente del mayor grado."],["Una ra\xEDz entera","Seg\xFAn el teorema de la ra\xEDz racional, \xBFqu\xE9 tipo de ra\xEDz es necesariamente cualquier ra\xEDz racional de un polinomio m\xF3nico entero?","El denominador positivo divide al coeficiente principal 1, as\xED que debe valer 1."],["Sustituir el candidato en el polinomio","Tras obtener la lista de candidatos que permite el teorema de la ra\xEDz racional, \xBFqu\xE9 paso confirma que uno de ellos es realmente ra\xEDz?","La divisibilidad solo propone candidatos; la evaluaci\xF3n debe dar cero."]],["arithmetic-derivative","Derivada aritm\xE9tica",0,["Uno","\xBFCu\xE1nto vale la derivada aritm\xE9tica de un n\xFAmero primo?","La definici\xF3n asigna el valor 1 a todos los primos."],["La regla de Leibniz","\xBFQu\xE9 regla relaciona la derivada aritm\xE9tica de ab con las derivadas de los factores a y b?","Se cumple (ab)\u2032 = a\u2032b + ab\u2032."],["k \xB7 p\u1D4F\u207B\xB9","\xBFCu\xE1l es la derivada aritm\xE9tica de p\u1D4F para un primo p y un entero k \u2265 2?","Al derivar el producto de k factores p, cada t\xE9rmino de Leibniz conserva otros k \u2212 1 factores p."],["Cero","\xBFCu\xE1nto vale la derivada aritm\xE9tica de 1?","La regla de Leibniz aplicada a 1 = 1 \xB7 1 implica 1\u2032 = 2 \xB7 1\u2032."]]];var J=[["finite-probability","Probabilidad en espacios finitos",0,["Uno","En un espacio muestral finito, \xBFqu\xE9 probabilidad tiene el suceso seguro?","El suceso seguro contiene todos los resultados posibles y sus masas suman uno."],["Cero","\xBFQu\xE9 probabilidad tiene el suceso vac\xEDo en un espacio muestral finito?","No hay ning\xFAn resultado cuya probabilidad se pueda sumar."],["La suma de sus probabilidades","\xBFC\xF3mo se calcula la probabilidad de la uni\xF3n de dos sucesos incompatibles?","Como no hay resultados compartidos, cada masa se cuenta una sola vez."],["El n\xFAmero de casos favorables dividido por el n\xFAmero total de casos","Con resultados elementales equiprobables, \xBFc\xF3mo se calcula la probabilidad de un suceso?","Cada resultado pesa 1 dividido por el total; se suman los pesos de los resultados favorables."]],["conditional-independence","Independencia condicional",1,["La probabilidad marginal de A","Si A y B son independientes y P(B) > 0, \xBFa qu\xE9 equivale P(A dado B)?","Saber que ocurri\xF3 B deja intacta la probabilidad de A."],["La probabilidad conjunta dividida por la de la condici\xF3n","Si P(C) > 0, \xBFc\xF3mo se calcula P(A dado C) mediante sucesos sin condicionar?","Se restringe el espacio a C y se normaliza por su probabilidad."],["El producto de las dos probabilidades condicionadas","Si A y B son independientes dado C, con P(C) > 0, \xBFc\xF3mo se calcula P(A \u2229 B dado C)?","La factorizaci\xF3n sucede dentro del espacio condicionado."],["Pueden volverse dependientes al condicionar","Dos monedas justas se lanzan independientemente. Si se informa de que sali\xF3 exactamente una cara, \xBFqu\xE9 ocurre con la relaci\xF3n entre los dos resultados?","Con la condici\xF3n impuesta, conocer una moneda determina por completo la otra."]],["bernoulli-binomial","Bernoulli y binomial",1,["Un solo ensayo con dos resultados","\xBFQu\xE9 modela una variable de Bernoulli que vale 1 en caso de \xE9xito y 0 en caso de fallo?","Su \xFAnico par\xE1metro da la probabilidad de \xE9xito en un ensayo."],["El n\xFAmero de \xE9xitos","En n ensayos independientes con igual probabilidad de \xE9xito p, \xBFqu\xE9 cuenta la variable binomial?","Es la suma de las n variables indicadoras de \xE9xito."],["El n\xFAmero de maneras de situar k \xE9xitos entre n ensayos","En la masa binomial, \xBFqu\xE9 representa el coeficiente que multiplica a p\u1D4F(1 \u2212 p)\u207F\u207B\u1D4F?","Cada conjunto de posiciones de los \xE9xitos tiene la misma probabilidad."],["La probabilidad de \xE9xito multiplicada por el n\xFAmero de ensayos","\xBFC\xF3mo se calcula la media de una variable binomial en t\xE9rminos de n y p?","La linealidad de la esperanza suma una contribuci\xF3n p por cada ensayo."]],["hypergeometric-distribution","Distribuci\xF3n hipergeom\xE9trica",0,["Muestreo sin reemplazo","\xBFQu\xE9 forma de muestreo de una poblaci\xF3n finita da lugar al recuento hipergeom\xE9trico?","Cada extracci\xF3n retira un elemento de la poblaci\xF3n antes de la siguiente."],["Una binomial","Si en cada extracci\xF3n se repone el elemento y se mezcla la misma poblaci\xF3n, \xBFqu\xE9 modelo describe el n\xFAmero de \xE9xitos en un tama\xF1o de muestra fijo?","La probabilidad de \xE9xito se mantiene constante y las extracciones pueden modelarse como independientes."],["Disminuye tras extraer un \xE9xito","En una urna con objetos de dos clases, ambas presentes, \xBFqu\xE9 le sucede a la probabilidad del siguiente \xE9xito tras extraer uno sin reponerlo?","La proporci\xF3n de objetos de la clase de \xE9xito baja al retirar uno de ellos."],["El n\xFAmero total de \xE9xitos de la poblaci\xF3n","En un modelo hipergeom\xE9trico, \xBFqu\xE9 valor toma con certeza el n\xFAmero de \xE9xitos si se extrae toda la poblaci\xF3n?","Al extraer todos los elementos se incluyen todos los \xE9xitos y todos los fallos."]],["geometric-distribution","Distribuci\xF3n geom\xE9trica",1,["El primer \xE9xito","En ensayos independientes con la misma probabilidad de \xE9xito, \xBFqu\xE9 suceso detiene la espera que modela la distribuci\xF3n geom\xE9trica?","La variable registra cu\xE1ntos ensayos transcurren hasta que finalmente hay un \xE9xito."],["Los fallos seguidos de un \xE9xito","Si X cuenta ensayos hasta el primer \xE9xito, \xBFqu\xE9 secuencia corresponde al evento X = k?","Los primeros k \u2212 1 ensayos deben fallar y el ensayo k debe acertar."],["La distribuci\xF3n de la espera restante es la misma que al empezar","\xBFEn qu\xE9 consiste la propiedad sin memoria de la distribuci\xF3n geom\xE9trica tras observar solo fallos?","El futuro sigue teniendo ensayos independientes con la misma probabilidad de \xE9xito."],["El rec\xEDproco de la probabilidad de \xE9xito","Con probabilidad de \xE9xito p > 0 por ensayo, \xBFcu\xE1l es el n\xFAmero medio de ensayos hasta el primer \xE9xito, incluy\xE9ndolo?","La media de esta convenci\xF3n geom\xE9trica es 1/p."]],["poisson-exponential-waiting","Poisson y espera exponencial",1,["Una distribuci\xF3n de Poisson","En un proceso de Poisson homog\xE9neo, \xBFqu\xE9 distribuci\xF3n tiene el n\xFAmero de llegadas durante un intervalo fijo?","Su par\xE1metro es la tasa por unidad de tiempo multiplicada por la duraci\xF3n del intervalo."],["Una distribuci\xF3n exponencial","En un proceso de Poisson homog\xE9neo, \xBFqu\xE9 distribuci\xF3n tiene el tiempo hasta la primera llegada?","Esperar m\xE1s de t equivale a tener cero llegadas durante t."],["e\u207B\u02E3, con x igual a la tasa por la duraci\xF3n","\xBFCu\xE1l es la probabilidad de cero llegadas en un intervalo de un proceso de Poisson homog\xE9neo?","Al evaluar la masa de Poisson en cero, queda la exponencial del negativo del n\xFAmero esperado."],["La espera media se reduce a la mitad","Si se duplica la tasa de un proceso de Poisson homog\xE9neo, \xBFqu\xE9 sucede con el tiempo medio entre llegadas?","La espera media es el rec\xEDproco de la tasa."]],["large-numbers-law","Ley de los grandes n\xFAmeros",0,["La media de la poblaci\xF3n","En una muestra de observaciones independientes de la misma distribuci\xF3n y con media finita, \xBFhacia qu\xE9 valor se estabiliza la media muestral?","La ley de los grandes n\xFAmeros aproxima la esperanza mediante repeticiones."],["La probabilidad de cara sigue siendo la misma","Tras diez cruces en lanzamientos de una moneda justa e independiente, \xBFqu\xE9 ocurre con la probabilidad de cara en el siguiente lanzamiento?","La estabilizaci\xF3n de la frecuencia no exige compensar resultados pasados en un lanzamiento individual."],["La probabilidad de superar cualquier error fijo tiende a cero","\xBFQu\xE9 significa que la media muestral converge en probabilidad a la media poblacional?","Para cada \u03B5 > 0, la probabilidad de un error superior a \u03B5 tiende a cero."],["Una frecuencia relativa","Al aplicar la ley de los grandes n\xFAmeros a indicadoras de un suceso, \xBFqu\xE9 representa su media muestral?","Se divide el n\xFAmero de veces que ocurri\xF3 el suceso por el n\xFAmero total de pruebas."]],["discrete-expectation","Esperanza de variables discretas",0,["Una media ponderada por las probabilidades","\xBFC\xF3mo se obtiene la esperanza de una variable aleatoria discreta con soporte finito?","Cada valor contribuye multiplicado por la probabilidad de que ocurra."],["La suma de las esperanzas","\xBFCu\xE1l es la esperanza de X + Y si X e Y tienen esperanza finita, aunque dependan entre s\xED?","La linealidad de la esperanza no requiere independencia."],["La probabilidad del suceso","\xBFCu\xE1l es la esperanza de la variable que vale 1 cuando ocurre A y 0 en otro caso?","Solo el valor 1 contribuye a la media ponderada."],["Puede no ser un resultado posible","\xBFQu\xE9 ense\xF1a el valor esperado 3,5 de un dado justo de seis caras sobre la relaci\xF3n entre media y resultados individuales?","El centro de la distribuci\xF3n puede estar entre dos valores posibles."]],["covariance","Covarianza",0,["Se multiplican las desviaciones respecto a sus respectivas medias","\xBFQu\xE9 producto se promedia para obtener la covarianza de X e Y?","Se toma la esperanza de (X \u2212 E[X])(Y \u2212 E[Y])."],["Cero","Si X e Y son independientes y tienen segundos momentos finitos, \xBFcu\xE1nto vale su covarianza?","La esperanza del producto centrado se factoriza y cada factor tiene media cero."],["Pueden seguir siendo dependientes","Si X e Y tienen covarianza cero, \xBFqu\xE9 relaci\xF3n a\xFAn puede existir entre ellas?","Por ejemplo, con X sim\xE9trica alrededor de cero, Y = X\xB2 puede depender de X aunque la covarianza sea cero."],["La varianza","\xBFQu\xE9 cantidad particular se obtiene al calcular la covarianza de una variable consigo misma?","El producto de las dos desviaciones id\xE9nticas es una desviaci\xF3n al cuadrado."]],["normal-distribution","Distribuci\xF3n normal",0,["La media","\xBFQu\xE9 par\xE1metro fija el centro de simetr\xEDa de una distribuci\xF3n normal?","Cambiar la media traslada la campana sin alterar su forma."],["La desviaci\xF3n t\xEDpica","\xBFQu\xE9 par\xE1metro controla la anchura de una campana normal y tiene las mismas unidades que los datos?","Es la ra\xEDz cuadrada de la varianza."],["La normal est\xE1ndar","Si X es normal con media \u03BC y desviaci\xF3n t\xEDpica \u03C3 > 0, \xBFqu\xE9 distribuci\xF3n tiene (X \u2212 \u03BC)/\u03C3?","Restar centra la distribuci\xF3n y dividir fija la varianza en uno."],["Un medio","Para cualquier distribuci\xF3n normal no degenerada, \xBFqu\xE9 probabilidad queda por debajo de su media?","La simetr\xEDa reparte toda la masa a ambos lados y un punto individual tiene probabilidad cero."]],["maximum-likelihood","M\xE1xima verosimilitud",1,["El par\xE1metro del modelo","Una vez observados los datos, \xBFqu\xE9 se var\xEDa al maximizar la funci\xF3n de verosimilitud?","Los datos se toman como fijos y se comparan distintos par\xE1metros."],["Se convierte en suma","Cuando la verosimilitud es un producto de factores positivos, \xBFqu\xE9 le sucede al producto al tomar logaritmos?","El logaritmo de un producto es la suma de los logaritmos."],["Los mismos maximizadores","Si la verosimilitud es positiva, \xBFqu\xE9 relaci\xF3n hay entre los m\xE1ximos de la verosimilitud y de su logaritmo?","El logaritmo es estrictamente creciente y conserva el orden de los valores."],["La proporci\xF3n observada de \xE9xitos","Al ajustar por m\xE1xima verosimilitud una probabilidad de Bernoulli a ensayos independientes, \xBFqu\xE9 estimaci\xF3n se obtiene?","El m\xE1ximo de p\u1D4F(1 \u2212 p)\u207F\u207B\u1D4F se alcanza en p = k/n, incluidos los casos de borde."]],["sampling-bias","Sesgo de muestreo",1,["Sesgo de autoselecci\xF3n","Una encuesta sobre h\xE1bitos deportivos se publica en una p\xE1gina de corredores y responden quienes quieren. \xBFQu\xE9 riesgo ilustra el car\xE1cter voluntario de las respuestas?","Participar puede depender del inter\xE9s en el deporte y ese inter\xE9s est\xE1 relacionado con lo medido."],["Sesgo de cobertura","Una encuesta que pretende describir a toda una ciudad solo contacta con hogares que tienen tel\xE9fono fijo. \xBFQu\xE9 sesgo introduce excluir los dem\xE1s hogares del marco de muestreo?","Parte de la poblaci\xF3n objetivo no tiene posibilidad de ser seleccionada."],["Sesgo de no respuesta","Se eligen hogares al azar, pero quienes tienen horarios laborales largos responden mucho menos. \xBFQu\xE9 sesgo aparece si esos horarios est\xE1n relacionados con la variable medida?","La muestra que responde puede diferir sistem\xE1ticamente de la muestra que se contact\xF3."],["Reduce la variabilidad aleatoria, pero no corrige el sesgo por s\xED solo","En una encuesta sesgada, \xBFqu\xE9 efecto cabe esperar de aumentar el tama\xF1o sin cambiar el mecanismo de selecci\xF3n?","Repetir un mecanismo de selecci\xF3n defectuoso puede dar estimaciones precisas alrededor de un valor equivocado."]],["simpson-paradox","Paradoja de Simpson",2,["Una inversi\xF3n al agrupar los datos","\xBFQu\xE9 situaci\xF3n ilustra la paradoja de Simpson al comparar dos tratamientos por subgrupos y en el total?","El tratamiento con mejor tasa en cada subgrupo puede salir peor en el total."],["Los pesos de los grupos son distintos","\xBFQu\xE9 mecanismo permite que la tasa global favorezca otro tratamiento aunque las tasas dentro de cada grupo tengan la misma direcci\xF3n?","Las tasas globales son promedios ponderados con pesos que pueden diferir entre tratamientos."],["La inversi\xF3n queda descartada","Si dos tratamientos se comparan con los mismos pesos positivos en cada estrato y A tiene mejor tasa en todos, \xBFqu\xE9 ocurre con una posible inversi\xF3n al agregar?","La diferencia total es un promedio ponderado de diferencias estrictamente positivas."],["Las relaciones causales y c\xF3mo se generaron los datos","Al interpretar una inversi\xF3n de Simpson, \xBFqu\xE9 ayuda a decidir si conviene condicionar por el grupo para responder una pregunta causal?","El papel de la variable como posible causa com\xFAn, mediadora o colisionadora afecta la interpretaci\xF3n."]],["bootstrap","Remuestreo bootstrap",2,["Con reemplazo","En el bootstrap no param\xE9trico habitual, \xBFc\xF3mo se extraen datos de la muestra observada para formar una r\xE9plica?","La misma observaci\xF3n puede aparecer varias veces y otras pueden quedar fuera."],["El mismo estad\xEDstico de inter\xE9s","En cada muestra bootstrap, \xBFqu\xE9 se calcula para aproximar su variabilidad muestral?","Se aplica a cada r\xE9plica la misma regla que se us\xF3 con los datos originales."],["Es necesario respetar la dependencia del dise\xF1o","Si observaciones sucesivas est\xE1n fuertemente correlacionadas, \xBFqu\xE9 cautela exige el remuestreo bootstrap?","Remuestrear datos sueltos rompe la estructura temporal; remuestrear bloques puede preservarla en parte."],["Una aproximaci\xF3n a la distribuci\xF3n muestral","\xBFQu\xE9 representa el histograma de los valores de un estad\xEDstico calculado en muchas r\xE9plicas bootstrap?","La variaci\xF3n entre r\xE9plicas aproxima la que tendr\xEDa el estad\xEDstico en muestras nuevas bajo el m\xE9todo elegido."]],["markov-chains","Cadenas de M\xE1rkov",0,["El estado actual","En una cadena de M\xE1rkov, \xBFqu\xE9 informaci\xF3n del historial basta para determinar la distribuci\xF3n del siguiente estado?","Una vez conocido el presente, los estados anteriores no a\xF1aden informaci\xF3n a esa transici\xF3n."],["La suma es uno","Si P\u1D62\u2C7C significa la probabilidad de pasar de i a j, \xBFqu\xE9 se cumple al sumar una fila completa de la matriz de transici\xF3n?","Todos los destinos posibles desde i forman una distribuci\xF3n."],["La distribuci\xF3n estacionaria","\xBFC\xF3mo se llama una distribuci\xF3n fila \u03C0 que cumple \u03C0P = \u03C0 para una matriz de transici\xF3n P?","Una transici\xF3n deja intacta esa distribuci\xF3n."],["Permanece en ese estado con probabilidad uno","En una cadena de M\xE1rkov, \xBFqu\xE9 le ocurre a la trayectoria al llegar a un estado absorbente?","La probabilidad de la transici\xF3n de ese estado a s\xED mismo es uno."]],["probability-inequalities","Desigualdades de probabilidad",1,["La desigualdad de Markov","\xBFQu\xE9 desigualdad acota P(X \u2265 a) por E[X]/a para X no negativa y a > 0?","En el conjunto donde X \u2265 a, cada observaci\xF3n aporta al menos a a la esperanza."],["La desigualdad de Chebyshev","\xBFQu\xE9 desigualdad controla P(|X \u2212 \u03BC| \u2265 t) mediante la varianza y t\xB2?","Se obtiene aplicando Markov al cuadrado de la desviaci\xF3n."],["Una cota superior para la uni\xF3n de sucesos","\xBFQu\xE9 proporciona la suma de las probabilidades individuales aunque los sucesos puedan solaparse?","Contar un resultado m\xE1s de una vez solo puede aumentar la suma."],["La cota se divide por cuatro","En la cota de Chebyshev, \xBFqu\xE9 ocurre con el l\xEDmite superior al duplicar el umbral positivo de desviaci\xF3n, manteniendo fija la varianza?","El umbral aparece al cuadrado en el denominador."]],["statistical-power","Potencia estad\xEDstica",2,["Un error de tipo I","\xBFC\xF3mo se llama rechazar la hip\xF3tesis nula cuando en realidad es cierta?","El nivel de significaci\xF3n controla la probabilidad de ese falso positivo bajo la nula."],["Un error de tipo II","Para una alternativa concreta, \xBFc\xF3mo se llama no rechazar la nula cuando esa alternativa es verdadera?","Es pasar por alto un efecto que s\xED existe seg\xFAn el modelo."],["La probabilidad de rechazar la nula bajo una alternativa concreta","\xBFQu\xE9 representa la potencia de una prueba estad\xEDstica?","Es el complemento de la probabilidad del error de tipo II para esa alternativa."],["Suele aumentar con un tama\xF1o muestral mayor","En una prueba usual para una media, con efecto real, nivel de significaci\xF3n y dispersi\xF3n fijos, \xBFqu\xE9 ocurre con la potencia al aumentar la muestra?","La menor variabilidad de la media ayuda a distinguir el efecto del ruido muestral."]]];var $=[["graph-foundations","Fundamentos de grafos",1,["El grado de un v\xE9rtice","En un grafo simple no dirigido, \xBFc\xF3mo se llama el n\xFAmero de aristas incidentes en un v\xE9rtice?","En un grafo simple coincide con el n\xFAmero de vecinos del v\xE9rtice."],["Una componente conexa","\xBFC\xF3mo se llama un conjunto maximal de v\xE9rtices de un grafo no dirigido que est\xE1n comunicados entre s\xED por caminos?","No se puede a\xF1adir otro v\xE9rtice manteniendo la conectividad."],["El doble del n\xFAmero de aristas","\xBFA qu\xE9 equivale la suma de todos los grados de un grafo finito no dirigido?","Cada arista contribuye un grado en cada uno de sus extremos."],["Tiene que ser par","En un grafo finito no dirigido, \xBFqu\xE9 paridad tiene el n\xFAmero de v\xE9rtices de grado impar?","La suma de grados es par y los sumandos impares deben aparecer en cantidad par."]],["trees-graph-coloring","\xC1rboles y coloraci\xF3n",1,["Un grafo conexo y sin ciclos","\xBFQu\xE9 caracteriza a un \xE1rbol no dirigido?","La conectividad permite llegar a todos los v\xE9rtices y la ausencia de ciclos impide rutas simples alternativas."],["Un \xFAnico camino simple","\xBFCu\xE1ntos caminos simples hay entre dos v\xE9rtices distintos de un \xE1rbol?","Dos rutas simples distintas generar\xEDan un ciclo en alg\xFAn tramo."],["Tiene n \u2212 1 aristas","En un \xE1rbol finito con n v\xE9rtices, \xBFc\xF3mo se relaciona el n\xFAmero de aristas con n?","Retirar una hoja elimina un v\xE9rtice y una arista hasta quedar un solo v\xE9rtice."],["Dos colores bastan","\xBFCu\xE1ntos colores bastan siempre para colorear los v\xE9rtices de un \xE1rbol evitando vecinos del mismo color?","Se asigna un color a cada paridad de la distancia a una ra\xEDz elegida."]],["four-color-theorem","Teorema de los cuatro colores",1,["Como m\xE1ximo cuatro","\xBFCu\xE1ntos colores garantiza el teorema de los cuatro colores para colorear los v\xE9rtices de cualquier grafo plano simple?","El teorema da una cota superior uniforme para todos los grafos planos."],["Compartir un tramo de frontera","En la formulaci\xF3n para pa\xEDses con regiones conectadas, \xBFqu\xE9 tipo de contacto obliga a usar colores distintos?","Coincidir solo en un punto no cuenta como compartir un borde."],["El grafo completo de cuatro v\xE9rtices","\xBFQu\xE9 ejemplo de grafo plano muestra que tres colores no siempre bastan?","Se puede dibujar con un v\xE9rtice dentro de un tri\xE1ngulo y todas las parejas son adyacentes."],["El grafo de adyacencia de las regiones","Para aplicar el teorema de los cuatro colores, \xBFqu\xE9 objeto se construye al representar cada pa\xEDs por un v\xE9rtice y unir los que comparten un tramo de frontera?","El grafo permite traducir la restricci\xF3n de fronteras del mapa a una restricci\xF3n entre v\xE9rtices vecinos."]],["pigeonhole-principle","Principio del palomar",1,["Alguna caja contiene por lo menos dos objetos","Si se reparten n + 1 objetos entre n cajas, \xBFqu\xE9 garantiza el principio del palomar?","Con a lo sumo uno por caja solo habr\xEDa espacio para n objetos."],["Al menos \u2308N/k\u2309 objetos en una caja","Si N objetos se reparten entre k cajas, \xBFqu\xE9 cota inferior general se garantiza para la ocupaci\xF3n de la caja m\xE1s llena?","La mayor ocupaci\xF3n es entera y no puede ser inferior a la media."],["Dos enteros tienen diferencia divisible por m","Si escoges m + 1 enteros distintos y los agrupas por sus restos m\xF3dulo m, \xBFqu\xE9 se deduce?","Dos enteros caen en la misma clase de restos."],["Alguna caja queda vac\xEDa","Si se colocan menos objetos que cajas y cada objeto ocupa solo una caja, \xBFqu\xE9 garantiza contar las cajas ocupadas?","No puede haber m\xE1s cajas ocupadas que objetos asignados."]],["catalan-numbers","N\xFAmeros de Catalan",1,["Secuencias de par\xE9ntesis bien formadas","\xBFQu\xE9 objetos cuentan los n\xFAmeros de Catalan al disponer n pares de par\xE9ntesis?","Cada prefijo tiene tantas aperturas como cierres o m\xE1s, y el total termina equilibrado."],["Triangulaciones de un pol\xEDgono convexo de n + 2 lados","\xBFQu\xE9 configuraci\xF3n geom\xE9trica de diagonales se cuenta con el n\xFAmero de Catalan C\u2099?","Se dibujan diagonales que no se cruzan y dividen todo el pol\xEDgono en tri\xE1ngulos."],["El interior y el resto se cuentan por separado","Al deducir la recurrencia de Catalan para par\xE9ntesis, \xBFqu\xE9 separaci\xF3n produce el cierre que empareja la primera apertura?","Las secuencias interior y posterior son dos secuencias bien formadas independientes."],["Una \xFAnica configuraci\xF3n vac\xEDa","\xBFQu\xE9 interpretaci\xF3n combinatoria tiene C\u2080 = 1 en el recuento de secuencias de par\xE9ntesis?","Con cero pares, la secuencia de longitud cero es la \xFAnica opci\xF3n."]]],W=[["cellular-automata","Aut\xF3matas celulares",0,["El estado del vecindario","\xBFQu\xE9 informaci\xF3n usa la regla local de un aut\xF3mata celular para actualizar una celda?","La regla depende de un conjunto prefijado de celdas cercanas."],["La generaci\xF3n anterior completa","En un aut\xF3mata celular con actualizaci\xF3n simult\xE1nea, \xBFde qu\xE9 generaci\xF3n se toman los datos para calcular todos los nuevos estados?","Calcular una celda primero no modifica los datos que reciben las dem\xE1s."],["Un n\xFAmero finito de configuraciones","\xBFQu\xE9 propiedad de un aut\xF3mata determinista sobre una cuadr\xEDcula finita con estados finitos obliga a que su \xF3rbita acabe repiti\xE9ndose?","Dos instantes deben compartir estado global y entonces comparten toda su evoluci\xF3n futura."],["Las reglas locales generan patrones globales","\xBFQu\xE9 relaci\xF3n entre escala peque\xF1a y escala grande ilustra un aut\xF3mata celular?","Al repetir una regla por toda la cuadr\xEDcula pueden aparecer estructuras que abarcan muchas celdas."]],["life-patterns","Patrones del Juego de la Vida",0,["Una naturaleza muerta","En el Juego de la Vida de Conway, \xBFc\xF3mo se llama un patr\xF3n que permanece id\xE9ntico en cada generaci\xF3n?","El bloque de cuatro celdas es un ejemplo estable."],["Un oscilador","En el Juego de la Vida, \xBFc\xF3mo se llama un patr\xF3n que cambia pero recupera su forma y posici\xF3n tras un n\xFAmero fijo de generaciones?","El parpadeador recupera su estado inicial tras dos pasos."],["Una nave","En el Juego de la Vida, \xBFc\xF3mo se llama un patr\xF3n que recupera su forma peri\xF3dicamente, pero trasladado?","El planeador vuelve a su forma una y otra vez en otra posici\xF3n."],["Una pistola","En el Juego de la Vida, \xBFqu\xE9 tipo de patr\xF3n estacionario emite naves de forma peri\xF3dica?","La pistola de Gosper genera un flujo repetido de planeadores."]],["lorenz-attractor","Atractor de Lorenz",1,["La forma de dos l\xF3bulos","\xBFQu\xE9 rasgo visual suele identificar al atractor cl\xE1sico de Lorenz?","La trayectoria gira alrededor de dos regiones y cambia entre ellas."],["El sistema sigue siendo determinista","En el sistema de Lorenz, \xBFqu\xE9 implica conocer exactamente un estado inicial si las ecuaciones determinan una soluci\xF3n \xFAnica?","Las ecuaciones fijan una trayectoria, aunque predecirla con medidas aproximadas sea dif\xEDcil."],["Las trayectorias inicialmente cercanas pueden separarse","\xBFQu\xE9 significa sensibilidad a las condiciones iniciales en el atractor de Lorenz?","Errores iniciales peque\xF1os pueden crecer hasta dificultar la predicci\xF3n."],["La trayectoria permanece en una regi\xF3n acotada","Si una trayectoria de Lorenz est\xE1 en el atractor, \xBFqu\xE9 ocurre con sus valores pese a que el movimiento sea irregular?","La irregularidad puede coexistir con movimiento confinado."]],["lyapunov-stability-chaos","Estabilidad y exponentes de Lyapunov",1,["Los estados cercanos permanecen cerca","\xBFQu\xE9 exige la estabilidad de Lyapunov alrededor de un equilibrio para perturbaciones iniciales suficientemente peque\xF1as?","A cada margen de tolerancia le corresponde un margen inicial que garantiza permanecer cerca."],["Los estados cercanos adem\xE1s convergen al equilibrio","\xBFQu\xE9 a\xF1ade la estabilidad asint\xF3tica a la estabilidad de Lyapunov?","La trayectoria permanece cerca y la distancia al equilibrio tiende a cero."],["El crecimiento exponencial medio de perturbaciones peque\xF1as","\xBFQu\xE9 cuantifica un exponente de Lyapunov positivo a lo largo de una \xF3rbita?","Describe c\xF3mo se amplifica, en promedio y en una direcci\xF3n, una perturbaci\xF3n infinitesimal."],["La distancia al equilibrio puede persistir","En un oscilador arm\xF3nico ideal sin rozamiento, \xBFpor qu\xE9 el equilibrio es estable pero no asint\xF3ticamente estable?","Una perturbaci\xF3n peque\xF1a produce una \xF3rbita que sigue oscilando sin perder energ\xEDa."]],["first-integrals","Primeras integrales",1,["Una cantidad constante a lo largo de la soluci\xF3n","\xBFQu\xE9 es una primera integral de un sistema din\xE1mico?","Su valor permanece igual mientras se recorre la trayectoria."],["Una curva o superficie de nivel","Si H es una primera integral, \xBFqu\xE9 conjunto contiene a la trayectoria que parte de un estado con H = c?","Todo punto de la trayectoria conserva exactamente ese valor c."],["Su derivada a lo largo del campo es cero","Para una funci\xF3n diferenciable H y un sistema x\u2032 = F(x), \xBFqu\xE9 relaci\xF3n comprueba que H es una primera integral?","La regla de la cadena da dH/dt = \u2207H \xB7 F."],["La energ\xEDa mec\xE1nica","En un oscilador ideal sin rozamiento, \xBFqu\xE9 magnitud se conserva al intercambiar energ\xEDa cin\xE9tica y potencial?","Aunque cada parte oscila, su suma es constante."]]],Z=[["sierpinski-triangle","Tri\xE1ngulo de Sierpinski",1,["Tres tri\xE1ngulos de esquina","En cada iteraci\xF3n del tri\xE1ngulo de Sierpinski cl\xE1sico, \xBFqu\xE9 se conserva de cada tri\xE1ngulo anterior?","Se elimina el interior de la pieza central formada al unir puntos medios."],["La mitad","\xBFPor qu\xE9 factor se escala la longitud de lado de cada tri\xE1ngulo hijo con respecto al de su tri\xE1ngulo padre en Sierpinski?","Cada lado hijo une un v\xE9rtice con el punto medio de un lado."],["log 3 / log 2","\xBFQu\xE9 dimensi\xF3n de semejanza resulta para el tri\xE1ngulo de Sierpinski cl\xE1sico?","Hay tres copias con escala lineal 1/2, por lo que 3(1/2)\u1D48 = 1."],["Tres cuartos","En cada paso del tri\xE1ngulo de Sierpinski, \xBFqu\xE9 fracci\xF3n del \xE1rea de la aproximaci\xF3n anterior se conserva?","Tres copias con un cuarto del \xE1rea cada una conservan 3/4."]],["sierpinski-carpet","Alfombra de Sierpinski",1,["Se elimina el cuadrado central","Al subdividir cada cuadrado de la alfombra de Sierpinski en una cuadr\xEDcula 3 \xD7 3, \xBFqu\xE9 casilla se elimina?","Las ocho casillas perif\xE9ricas se mantienen para repetir la regla."],["Ocho","\xBFCu\xE1ntas copias reducidas de s\xED misma componen la alfombra cl\xE1sica de Sierpinski?","De nueve casillas, se descarta solo la central."],["log 8 / log 3","\xBFQu\xE9 dimensi\xF3n de semejanza tiene la alfombra de Sierpinski cl\xE1sica?","Cada copia tiene escala lineal 1/3 y quedan ocho copias autosimilares."],["Tiende a cero","\xBFQu\xE9 hace el \xE1rea de las aproximaciones sucesivas a la alfombra de Sierpinski?","Cada iteraci\xF3n conserva 8/9 del \xE1rea anterior, una proporci\xF3n estrictamente inferior a uno."]],["menger-sponge","Esponja de Menger",1,["Se retiran el cubo central y los seis centros de caras","\xBFQu\xE9 piezas se retiran en el primer paso de la esponja de Menger tras dividir un cubo en 27 cubos iguales?","Los tres t\xFAneles de secci\xF3n cuadrada comparten el cubo central."],["Veinte cubos","De los 27 cubos peque\xF1os de cada bloque de la esponja de Menger, \xBFcu\xE1ntos se conservan?","Se quitan siete cubos y la regla se repite en los veinte restantes."],["log 20 / log 3","\xBFQu\xE9 dimensi\xF3n de semejanza se obtiene para la esponja de Menger?","Los veinte cubos hijos tienen lado igual a un tercio del original."],["Se multiplica por 20/27","\xBFC\xF3mo cambia el volumen de la aproximaci\xF3n a la esponja de Menger en cada paso?","Cada cubo conservado tiene 1/27 del volumen de su padre."]],["iterated-function-systems","Sistemas de funciones iteradas",2,["Una colecci\xF3n finita de transformaciones","En un sistema de funciones iteradas contractivo, \xBFqu\xE9 se aplica repetidamente para construir la figura?","Cada funci\xF3n produce una copia transformada y se toma la uni\xF3n de las im\xE1genes."],["Una copia a menor escala en el caso de una semejanza contractiva","\xBFQu\xE9 produce una semejanza contractiva cuando se aplica a una figura geom\xE9trica?","Todas las distancias se multiplican por una misma raz\xF3n entre cero y uno."],["El atractor es la uni\xF3n de sus propias im\xE1genes","\xBFQu\xE9 ecuaci\xF3n de invariancia cumple el atractor compacto A de un sistema contractivo con mapas f\u1D62?","Tomar la uni\xF3n de todos los f\u1D62(A) reproduce A."],["Convergen a la misma figura l\xEDmite","Con mapas contractivos sobre un espacio completo, \xBFqu\xE9 destino tienen dos compactos no vac\xEDos iniciales al iterar la uni\xF3n de im\xE1genes?","La operaci\xF3n sobre compactos es una contracci\xF3n en la distancia de Hausdorff."]],["fractal-measure-dimension","Medida y dimensi\xF3n fractal",2,["Aumentar la resoluci\xF3n","En un recuento por cajas de lado \u03B5, \xBFqu\xE9 significa hacer cada vez menor \u03B5?","La cuadr\xEDcula distingue detalles a escalas m\xE1s peque\xF1as."],["Contar las cajas que tocan el conjunto","\xBFQu\xE9 cantidad se compara al observar un conjunto con cuadr\xEDculas de distintas escalas para estimar su dimensi\xF3n por cajas?","El ritmo de crecimiento del recuento aporta la dimensi\xF3n, si existe el l\xEDmite correspondiente."],["La pendiente de log N(\u03B5) frente a log(1/\u03B5)","\xBFQu\xE9 pendiente aproximas al estimar la dimensi\xF3n por cajas a partir de una ley N(\u03B5) \u2248 C \u03B5\u207B\u1D48?","Al tomar logaritmos, el exponente d multiplica log(1/\u03B5)."],["Es posible tener longitud total infinita y \xE1rea nula","\xBFQu\xE9 combinaci\xF3n de medidas puede mostrar una curva fractal plana como la curva cl\xE1sica de Koch?","Su longitud aumenta sin l\xEDmite y su dimensi\xF3n es menor que dos, por lo que tiene \xE1rea plana cero."]]];var oe=[["Probabilidad",["monty-hall","El problema de Monty Hall",["En el Monty Hall cl\xE1sico eliges una de tres puertas. El presentador sabe d\xF3nde est\xE1 el premio y siempre abre una de las otras dos para mostrar una cabra. \xBFQu\xE9 estrategia maximiza la probabilidad de ganar?","Cambiar de puerta","Mantener la puerta inicial","Elegir siempre la puerta central","Ambas estrategias dan la misma probabilidad","Cambiar gana cuando la elecci\xF3n inicial falla, lo que ocurre dos de cada tres veces."],["En el problema cl\xE1sico de Monty Hall, despu\xE9s de que el concursante elija una de las tres puertas, \xBFqu\xE9 regla sigue el presentador al abrir una puerta?","Abre siempre una puerta no elegida que esconde una cabra","Abre una puerta al azar, aunque haya premio","Solo ofrece cambiar cuando acertaste al principio","Abre siempre la puerta que elegiste","La acci\xF3n del presentador aporta informaci\xF3n porque est\xE1 condicionada por d\xF3nde se esconde el premio."],["En Monty Hall con 100 puertas, el premio se coloca con igual probabilidad tras cualquiera de ellas. Tras tu elecci\xF3n, el presentador siempre abre 98 puertas con cabra entre las que descartaste. \xBFQu\xE9 probabilidad tienes de ganar si cambias a la otra puerta cerrada?","99/100","1/2","1/100","98/100","Cambiar gana en los 99 casos de cada 100 en los que la elecci\xF3n original era incorrecta."]],["birthday-paradox","La paradoja del cumplea\xF1os",["\xBFQu\xE9 coincidencia busca la paradoja del cumplea\xF1os?","Que al menos dos personas compartan cumplea\xF1os","Que alguien cumpla a\xF1os hoy","Que todos hayan nacido el mismo d\xEDa","Que todos tengan edades distintas","Vale cualquier pareja del grupo. La fecha concreta puede ser cualquiera."],["Para calcular la probabilidad de que al menos dos personas de un grupo compartan cumplea\xF1os, \xBFqu\xE9 suceso complementario conviene calcular primero?","Que todos tengan fechas distintas","Que haya exactamente una pareja","Que haya tres cumplea\xF1os iguales","Que la fecha repetida sea el 1 de enero","El complemento permite multiplicar la probabilidad de evitar todas las fechas anteriores al a\xF1adir a cada persona."],["Si 23 personas tienen cumplea\xF1os independientes y uniformes entre 365 fechas, \xBFqu\xE9 producto da la probabilidad de que todos sean distintos?","365/365 \xB7 364/365 \xB7 \u2026 \xB7 343/365","(364/365)\xB2\xB3","23/365 \xB7 22/365 \xB7 \u2026 \xB7 1/365","1 \u2212 (364/365)\xB2\xB3","Tras asignar 22 fechas distintas, quedan 343 disponibles para la \xFAltima persona."]],["bayes-theorem","El teorema de Bayes",["\xBFQu\xE9 permite actualizar el teorema de Bayes?","La probabilidad de una hip\xF3tesis al observar evidencia","La media sin conocer datos nuevos","El tama\xF1o de una muestra pasada","La definici\xF3n de independencia","La evidencia cambia el peso que damos a cada hip\xF3tesis seg\xFAn lo probable que sea observarla bajo esa hip\xF3tesis."],["En un problema de diagn\xF3stico, \xBFqu\xE9 es la tasa base?","La frecuencia de la condici\xF3n antes de conocer el resultado","La probabilidad de positivo entre quienes tienen la condici\xF3n","La proporci\xF3n de falsos positivos","La probabilidad de repetir la prueba","La tasa base es una probabilidad previa. Puede influir mucho en lo que significa un positivo."],["Al aplicar el teorema de Bayes, dos hip\xF3tesis tienen probabilidades previas positivas y distintas. Ambas asignan a la evidencia la misma probabilidad, mayor que cero. \xBFC\xF3mo cambia el cociente entre las probabilidades de las dos hip\xF3tesis despu\xE9s de observar la evidencia?","Queda igual","Se vuelve igual a uno","Se invierte","Se duplica","Al aplicar Bayes a ambas y dividir, las dos verosimilitudes iguales se cancelan."]]],["Geometr\xEDa",["euler-line","La recta de Euler",["\xBFQu\xE9 tres puntos de un tri\xE1ngulo no equil\xE1tero est\xE1n alineados en la recta de Euler?","Circuncentro, baricentro y ortocentro","Incentro, ortocentro y punto de Fermat","Los tres v\xE9rtices","Los tres pies de las alturas","La recta pasa por el centro de la circunferencia circunscrita, el cruce de las medianas y el cruce de las alturas."],["En la recta de Euler de un tri\xE1ngulo no equil\xE1tero, \xBFqu\xE9 punto est\xE1 entre el circuncentro y el ortocentro, al doble de distancia del ortocentro que del circuncentro?","El baricentro","El incentro","El centro de la circunferencia de nueve puntos","El punto de Fermat","La distancia del circuncentro al baricentro es la mitad de la que separa el baricentro del ortocentro."],["En un tri\xE1ngulo rect\xE1ngulo, \xBFcon qu\xE9 recta coincide la recta de Euler?","La mediana que parte del \xE1ngulo recto","La bisectriz de cualquier \xE1ngulo agudo","La recta de la hipotenusa","La mediatriz de cualquier cateto","El ortocentro est\xE1 en el v\xE9rtice recto y el circuncentro en el punto medio de la hipotenusa."]],["pick-theorem","El teorema de Pick",["\xBFEn qu\xE9 tipo de pol\xEDgonos se aplica directamente el teorema de Pick?","Pol\xEDgonos simples con v\xE9rtices en una cuadr\xEDcula entera","Cualquier pol\xEDgono con lados curvos","Solo pol\xEDgonos regulares","Solo tri\xE1ngulos equil\xE1teros","Pick obtiene el \xE1rea contando puntos de la cuadr\xEDcula interiores y en la frontera."],["En un pol\xEDgono simple con v\xE9rtices en la cuadr\xEDcula entera, I es el n\xFAmero de puntos de la cuadr\xEDcula en su interior y B el n\xFAmero de puntos en su borde. \xBFQu\xE9 f\xF3rmula da el \xE1rea seg\xFAn el teorema de Pick?","I + B/2 \u2212 1","I/2 + B \u2212 1","I + B \u2212 1","I \xB7 B/2","Un punto de borde contribuye con la mitad del peso de un punto interior, y la f\xF3rmula resta una unidad."],["Dos pol\xEDgonos simples con v\xE9rtices en la cuadr\xEDcula entera tienen igual \xE1rea. Seg\xFAn el teorema de Pick, si el primero tiene cuatro puntos de la cuadr\xEDcula m\xE1s en el borde que el segundo, \xBFc\xF3mo se comparan sus cantidades de puntos interiores?","Tiene dos menos","Tiene cuatro menos","Tiene dos m\xE1s","Tiene los mismos","Para conservar el \xE1rea, el aumento de B/2 debe compensarse con una disminuci\xF3n igual en I."]],["heron-formula","La f\xF3rmula de Her\xF3n",["\xBFQu\xE9 datos bastan para hallar el \xE1rea de un tri\xE1ngulo con Her\xF3n?","Las longitudes de sus tres lados","Solo su per\xEDmetro","Dos \xE1ngulos sin ninguna longitud","La longitud de un lado cualquiera","El semiper\xEDmetro y las diferencias entre este y cada lado determinan el \xE1rea."],["\xBFQu\xE9 significa s en la f\xF3rmula de Her\xF3n?","La mitad de la suma de los tres lados","El lado m\xE1s largo","La suma de dos lados","La altura sobre el lado m\xE1s corto","El semiper\xEDmetro es s = (a + b + c)/2."],["En un tri\xE1ngulo con dos lados de longitud fija, el tercero se acerca a la suma de esas dos longitudes. \xBFQu\xE9 predice la f\xF3rmula de Her\xF3n sobre el \xE1rea?","El \xE1rea tiende a cero","El \xE1rea tiende al semiper\xEDmetro","El \xE1rea crece sin l\xEDmite","El \xE1rea tiende a la mitad del producto de los lados menores","Uno de los factores, la diferencia entre semiper\xEDmetro y lado mayor, tiende a cero."]]],["N\xFAmeros",["euclid-infinitely-many-primes","La infinitud de los primos",["En la prueba de Euclides que multiplica los primos de una lista finita y suma uno al producto, \xBFqu\xE9 se concluye sobre la cantidad total de n\xFAmeros primos?","Hay infinitos","Todos son impares","Son consecutivos a partir de cierto punto","Hay tantos como compuestos en cada intervalo","Toda lista finita de primos deja fuera al menos uno."],["En la prueba de Euclides sobre la infinitud de los primos, se multiplica una lista finita de primos y se suma uno al resultado. \xBFQu\xE9 resto se obtiene al dividir ese n\xFAmero por cualquiera de los primos de la lista?","Uno","Cero","El producto menos uno","Depende del primo","El producto es divisible por cada primo de la lista y sumar uno cambia el resto a uno."],["En la prueba de Euclides sobre la infinitud de los primos, se supone que una lista finita contiene todos los primos. Si el producto de los primos de la lista m\xE1s uno es compuesto, \xBFc\xF3mo se contradice esa suposici\xF3n?","Cualquier divisor primo suyo queda fuera de la lista","Uno de sus divisores primos debe ser el mayor de la lista","Todo n\xFAmero compuesto carece de divisores primos","El producto inicial era necesariamente primo","El n\xFAmero construido tiene alg\xFAn divisor primo y ninguno de los primos de la lista puede dividirlo."]],["euclid-euler-perfect-numbers","El teorema de Euclides\u2013Euler",["\xBFCu\xE1ndo se llama perfecto a un entero positivo?","Cuando es la suma de sus divisores positivos propios","Cuando es divisible solo por s\xED mismo","Cuando es un cuadrado","Cuando tiene un n\xFAmero impar de divisores","Por ejemplo, 6 = 1 + 2 + 3. Los divisores propios excluyen al n\xFAmero mismo."],["\xBFQu\xE9 clase de n\xFAmeros perfectos caracteriza Euclides\u2013Euler?","Los pares","Los impares","Solo los menores de cien","Solo los que son potencias de dos","Los perfectos pares son exactamente los de la forma 2\u1D56\u207B\xB9(2\u1D56 \u2212 1), con 2\u1D56 \u2212 1 primo."],["Al estudiar los n\xFAmeros de Mersenne, \xBFqu\xE9 se puede concluir sobre 2\u1D56 \u2212 1 si el exponente entero positivo p es compuesto?","2\u1D56 \u2212 1 es compuesto","2\u1D56 \u2212 1 es siempre primo","2\u1D56 \u2212 1 es par","Depende \xFAnicamente de si p es par","Si p = ab con a, b mayores que uno, 2\u1D43 \u2212 1 es un divisor propio de 2\u1D56 \u2212 1."]],["bezout-identity","La identidad de B\xE9zout",["\xBFQu\xE9 expresa la identidad de B\xE9zout como combinaci\xF3n entera de a y b?","Su m\xE1ximo com\xFAn divisor","Su cociente exacto","Su media geom\xE9trica","El n\xFAmero de sus divisores","Existen enteros x e y tales que ax + by = mcd(a,b)."],["Seg\xFAn la identidad de B\xE9zout, \xBFqu\xE9 condici\xF3n deben cumplir los enteros a y b para que existan enteros x e y tales que ax + by = 1?","a y b son coprimos","a y b son ambos pares","a y b son ambos compuestos","a y b tienen el mismo signo","Una combinaci\xF3n entera siempre es m\xFAltiplo del m\xE1ximo com\xFAn divisor."],["Si los enteros a, b, x e y satisfacen ax + by = 1 y b > 1, \xBFqu\xE9 relaci\xF3n tiene x con a en la aritm\xE9tica m\xF3dulo b?","Es un inverso multiplicativo de a","Es el inverso aditivo de a","Es siempre congruente con cero","Es siempre congruente con a","Reduciendo la igualdad m\xF3dulo b queda ax \u2261 1."]]],["Fractales",["koch-snowflake","El copo de Koch",["\xBFQu\xE9 combinaci\xF3n muestra el copo de Koch en el l\xEDmite?","\xC1rea finita y per\xEDmetro infinito","\xC1rea infinita y per\xEDmetro finito","\xC1rea y per\xEDmetro nulos","\xC1rea y per\xEDmetro enteros","Los lados crecen en longitud total y la suma de las \xE1reas a\xF1adidas converge."],["En la construcci\xF3n del copo de Koch a partir de un tri\xE1ngulo equil\xE1tero, \xBFpor qu\xE9 factor se multiplica el per\xEDmetro en cada iteraci\xF3n?","4/3","3/4","4","1/3","Cada segmento se sustituye por cuatro de un tercio de su longitud."],["Al construir el copo de Koch, se a\xF1aden tri\xE1ngulos en cada iteraci\xF3n. \xBFPor qu\xE9 factor se multiplica el \xE1rea total a\xF1adida en una iteraci\xF3n respecto al \xE1rea a\xF1adida en la anterior, a partir de la segunda adici\xF3n?","4/9","4/3","1/3","1/9","Se a\xF1aden cuatro veces m\xE1s tri\xE1ngulos con un noveno del \xE1rea individual."]],["cantor-set","El conjunto de Cantor",["Al construir el conjunto de Cantor cl\xE1sico a partir del intervalo [0, 1], \xBFqu\xE9 parte de cada segmento restante se elimina en cada paso?","El tercio central abierto de cada segmento","Los extremos de todos los segmentos","La mitad izquierda de cada segmento","Todos los n\xFAmeros irracionales","Se conservan los dos tercios exteriores y los extremos del intervalo eliminado."],["En la construcci\xF3n del conjunto de Cantor a partir de [0, 1], se quita el tercio central abierto de cada segmento en cada paso. \xBFCu\xE1l es la longitud total que queda tras n pasos?","(2/3)\u207F","(1/3)\u207F","(3/2)\u207F","1 \u2212 (2/3)\u207F","En cada paso queda una proporci\xF3n de dos tercios de la longitud anterior."],["\xBFQu\xE9 caracteriza, en base tres, a los n\xFAmeros del intervalo [0, 1] que pertenecen al conjunto de Cantor?","Admiten una expansi\xF3n que usa solo 0 y 2","Toda expansi\xF3n debe contener un 1","Su expansi\xF3n termina siempre en ceros","Solo pueden tener un d\xEDgito 2","Elegir 0 o 2 equivale a tomar el tercio izquierdo o derecho. Los extremos pueden tener dos expansiones."]],["mandelbrot-set","El conjunto de Mandelbrot",["Para decidir si un par\xE1metro complejo c pertenece al conjunto de Mandelbrot, se repite la operaci\xF3n z \u21A6 z\xB2 + c empezando en z = 0. \xBFQu\xE9 propiedad se comprueba?","Si la \xF3rbita iniciada en cero permanece acotada","Si el par\xE1metro tiene parte imaginaria nula","Si la \xF3rbita visita todos los puntos vecinos","Si todas las iteraciones son n\xFAmeros reales","Para cada par\xE1metro complejo c se itera z \u21A6 z\xB2 + c desde cero."],["En la iteraci\xF3n cuadr\xE1tica z \u21A6 z\xB2 + c, \xBFqu\xE9 se mantiene fijo y qu\xE9 se var\xEDa al representar el conjunto de Mandelbrot y un conjunto de Julia?","Mandelbrot var\xEDa c y Julia fija c y var\xEDa el punto inicial","Ambos var\xEDan c, pero Julia empieza siempre en 1","Mandelbrot usa solo puntos reales","Julia sustituye el cuadrado por una ra\xEDz","Uno representa par\xE1metros y el otro describe la din\xE1mica para un par\xE1metro dado."],["En la iteraci\xF3n z \u21A6 z\xB2 + c iniciada en cero, \xBFqu\xE9 \xF3rbita explica que c = \u22122 pertenezca al conjunto de Mandelbrot?","La \xF3rbita es 0, \u22122, 2, 2, \u2026","La \xF3rbita se mantiene siempre en cero","La \xF3rbita es 0, \u22122, \u22124, \u22126, \u2026","Todos los reales negativos pertenecen","El punto 2 queda fijo bajo z \u21A6 z\xB2 \u2212 2. Alcanzar m\xF3dulo 2 por s\xED solo no demuestra escape."]]],["Combinatoria y juegos",["towers-of-hanoi","Torres de Hanoi",["\xBFQu\xE9 restricci\xF3n rige las torres de Hanoi?","Un disco grande no puede quedar encima de uno menor","Solo se pueden mover discos pares","Cada torre puede alojar un solo disco","Est\xE1 prohibido usar la torre intermedia","Solo se mueve el disco superior y se respeta el orden de tama\xF1os en cada torre."],["En las Torres de Hanoi con tres postes, justo antes de mover el disco mayor del poste de origen al de destino, \xBFen qu\xE9 poste deben estar todos los discos menores?","En la torre auxiliar","En la torre de destino","Repartidos entre el origen y el destino","En la torre de origen","El origen debe dejar libre el disco mayor y el destino no puede contener ning\xFAn disco m\xE1s peque\xF1o."],["En las Torres de Hanoi con tres postes, T(n) es el m\xEDnimo de movimientos para trasladar una pila de n discos a otro poste. \xBFQu\xE9 recurrencia cumple T(n) para n \u2265 2?","T(n) = 2T(n\u22121) + 1","T(n) = T(n\u22121) + 2","T(n) = n \xB7 T(n\u22121)","T(n) = T(n\u22121) + n","Se trasladan los n\u22121 discos peque\xF1os dos veces, antes y despu\xE9s del movimiento del disco mayor."]],["burnside-lemma","El lema de Burnside",["\xBFQu\xE9 ayuda a contar el lema de Burnside?","Configuraciones distintas salvo simetr\xEDas","Solo permutaciones de n\xFAmeros primos","Probabilidades de eventos independientes","Longitudes de trayectorias","Las configuraciones que se transforman unas en otras mediante una simetr\xEDa forman una \xF3rbita."],["Al aplicar el lema de Burnside para contar configuraciones distintas salvo simetr\xEDas, \xBFqu\xE9 cantidad se promedia sobre todos los elementos del grupo?","El n\xFAmero de configuraciones que deja fija cada una","El n\xFAmero de elementos que mueve cada una","El tama\xF1o de la mayor \xF3rbita","El n\xFAmero de generadores del grupo","Una configuraci\xF3n cuenta si queda id\xE9ntica despu\xE9s de aplicar la simetr\xEDa concreta."],["Un grupo finito G act\xFAa sobre un conjunto finito no vac\xEDo X. Ning\xFAn elemento de G distinto de la identidad deja fijo ning\xFAn punto de X. Seg\xFAn el lema de Burnside, \xBFcu\xE1l es la f\xF3rmula general para el n\xFAmero de \xF3rbitas?","|X|/|G|","|X| \xB7 |G|","|X| \u2212 |G|","|G|/|X|","La identidad fija todo X y las dem\xE1s contribuciones al promedio son cero."]],["inclusion-exclusion","Inclusi\xF3n y exclusi\xF3n",["\xBFQu\xE9 problema corrige el principio de inclusi\xF3n y exclusi\xF3n?","Contar varias veces los elementos compartidos","Dividir un conjunto en partes iguales","Ordenar los elementos de menor a mayor","Decidir si un n\xFAmero es primo","Al sumar los tama\xF1os de dos conjuntos, los elementos de su intersecci\xF3n se cuentan dos veces."],["Para contar los elementos de la uni\xF3n de tres conjuntos, ya has sumado sus tama\xF1os y restado los tama\xF1os de sus intersecciones por parejas. Seg\xFAn inclusi\xF3n y exclusi\xF3n, \xBFqu\xE9 operaci\xF3n falta?","Sumar la intersecci\xF3n de los tres","Restar la intersecci\xF3n de los tres","Dividir todo entre tres","Restar la uni\xF3n de los tres","Cada elemento com\xFAn a los tres se ha sumado tres veces y restado otras tres."],["Al contar los elementos de la uni\xF3n de cuatro conjuntos con inclusi\xF3n y exclusi\xF3n, \xBFcon qu\xE9 signo entra el n\xFAmero de elementos comunes a los cuatro?","Negativo","Positivo","Cero","Depende del tama\xF1o de la uni\xF3n","Los signos alternan seg\xFAn el n\xFAmero de conjuntos en la intersecci\xF3n, empezando por positivo."]]],["An\xE1lisis",["fourier-series","Series de Fourier",["\xBFQu\xE9 componentes usa una serie trigonom\xE9trica de Fourier?","Senos y cosenos de frecuencias arm\xF3nicas","Solo polinomios de grado creciente","\xDAnicamente exponenciales reales","Solo n\xFAmeros primos","Los arm\xF3nicos son m\xFAltiplos enteros de una frecuencia fundamental."],["Al calcular la serie trigonom\xE9trica de Fourier de una funci\xF3n par sobre un periodo centrado en el origen, \xBFqu\xE9 familia de t\xE9rminos tiene todos sus coeficientes iguales a cero?","Los de seno","Los de coseno","El t\xE9rmino constante y todos los cosenos","Todos los arm\xF3nicos","El producto de una funci\xF3n par por un seno es impar y su integral sim\xE9trica vale cero."],["Si una funci\xF3n peri\xF3dica es suave a trozos y tiene una discontinuidad de salto, \xBFa qu\xE9 valor converge su serie de Fourier en el punto del salto?","A la media de ambos l\xEDmites laterales","Siempre al l\xEDmite por la derecha","Siempre al l\xEDmite por la izquierda","Al valor aislado asignado a la funci\xF3n en ese punto","En un salto, la suma toma el punto medio de las dos alturas laterales."]],["newton-raphson","El m\xE9todo de Newton\u2013Raphson",["\xBFQu\xE9 problema busca resolver el m\xE9todo de Newton\u2013Raphson?","Encontrar una ra\xEDz de una funci\xF3n","Obtener su integral exacta","Contar sus puntos enteros","Hacerla peri\xF3dica","El m\xE9todo mejora una aproximaci\xF3n resolviendo en cada paso un problema lineal."],["En el m\xE9todo de Newton\u2013Raphson, si la derivada en el punto actual es distinta de cero, \xBFc\xF3mo se obtiene geom\xE9tricamente la siguiente aproximaci\xF3n a la ra\xEDz?","Del cruce de la recta tangente con el eje horizontal","Del m\xE1ximo local m\xE1s cercano","Del cruce de la recta normal con el eje vertical","Del promedio de todas las ra\xEDces","Se busca d\xF3nde vale cero la aproximaci\xF3n lineal a la funci\xF3n en el punto actual."],["Al buscar una ra\xEDz con Newton\u2013Raphson, la derivada en el punto actual vale cero y la funci\xF3n en ese punto tiene un valor distinto de cero. \xBFQu\xE9 ocurre con el paso siguiente?","El paso de Newton no est\xE1 definido","Se obtiene una ra\xEDz exacta","La tangente corta el eje horizontal en dos lugares","La convergencia se vuelve cuadr\xE1tica autom\xE1ticamente","La tangente es horizontal y no corta el eje horizontal."]]],["\xC1lgebra y complejos",["groups-cosets-lagrange","El teorema de Lagrange",["\xBFCu\xE1l de estos n\xFAmeros divide siempre el orden de un grupo finito?","El orden de cualquiera de sus subgrupos","El doble de su orden","Su orden m\xE1s uno","El orden de cualquier otro grupo finito","Las clases laterales de un subgrupo reparten el grupo en partes del mismo tama\xF1o."],["\xBFQu\xE9 relaci\xF3n tienen los tama\xF1os de las clases laterales de un mismo subgrupo finito?","Todas tienen el tama\xF1o del subgrupo","Crecen de una en una","Solo coincide el tama\xF1o de las dos primeras","Siempre tienen tama\xF1o uno","Multiplicar por un representante da una biyecci\xF3n del subgrupo a su clase lateral."],["\xBFPor qu\xE9 un grupo de orden primo es c\xEDclico?","Todo elemento distinto de la identidad genera un subgrupo de orden igual al primo","Cualquier conjunto de orden primo tiene suma","Todo elemento tiene orden dos","Un grupo primo no tiene elemento identidad","El subgrupo generado por un elemento no neutro tiene orden mayor que uno y este debe dividir al primo."]],["gaussian-elimination","La eliminaci\xF3n de Gauss",["\xBFPara qu\xE9 sirve la eliminaci\xF3n de Gauss?","Transformar un sistema lineal para resolverlo","Factorizar cualquier polinomio","Ajustar una curva peri\xF3dica","Calcular derivadas parciales","Las operaciones elementales por filas conservan el conjunto de soluciones."],["Al aplicar la eliminaci\xF3n de Gauss a la matriz ampliada de un sistema lineal, \xBFqu\xE9 operaci\xF3n entre filas conserva el conjunto de soluciones?","Sumar a una fila un m\xFAltiplo de otra","Multiplicar una fila por cero","Cambiar solo el t\xE9rmino independiente","Borrar cualquier fila con pivote","La operaci\xF3n es reversible: basta restar el m\xFAltiplo que se sum\xF3."],["En la matriz ampliada de un sistema lineal, una fila tiene todos los coeficientes de las inc\xF3gnitas iguales a cero y el t\xE9rmino independiente igual a 1. \xBFQu\xE9 indica esa fila?","El sistema es incompatible","Hay una \xFAnica soluci\xF3n","El sistema tiene una variable libre","La fila representa una identidad","La fila representa la ecuaci\xF3n 0 = 1, que ninguna elecci\xF3n de inc\xF3gnitas satisface."]],["euler-identity","La identidad de Euler",["En la identidad de Euler, \xBFqu\xE9 valor tiene e elevado a i\u03C0, con i la unidad imaginaria?","\u22121","1","i","0","El \xE1ngulo \u03C0 lleva desde 1 hasta \u22121 en la circunferencia unidad."],["En el plano complejo, \xBFqu\xE9 transformaci\xF3n realiza multiplicar por e elevado a i\u03B8, con \u03B8 real?","Una rotaci\xF3n de \xE1ngulo \u03B8 alrededor del origen","Una homotecia de raz\xF3n \u03B8","Una traslaci\xF3n de longitud \u03B8","Una reflexi\xF3n en el eje real","Al multiplicar n\xFAmeros complejos se multiplican m\xF3dulos y se suman argumentos."],["\xBFQu\xE9 forma da la f\xF3rmula de Euler para e elevado a \u2212i\u03B8, con \u03B8 real?","cos \u03B8 \u2212 i sen \u03B8","\u2212cos \u03B8 \u2212 i sen \u03B8","\u2212cos \u03B8 + i sen \u03B8","sen \u03B8 \u2212 i cos \u03B8","El coseno es par y el seno es impar. Cambiar el signo del \xE1ngulo conjuga el n\xFAmero complejo."]]],["Topolog\xEDa e infinito",["mobius-strip","La banda de M\xF6bius",["\xBFC\xF3mo se construye una banda de M\xF6bius con papel?","Uniendo los extremos tras dar media vuelta a uno","Uniendo los extremos sin giro","Pegando las dos caras a lo largo","Dando dos vueltas completas a un extremo","La media vuelta identifica el lado izquierdo de un extremo con el derecho del otro."],["\xBFCu\xE1ntas componentes tiene el borde de una banda de M\xF6bius?","Una","Dos","Tres","Ninguna","El giro conecta los dos lados largos de la tira en un solo recorrido cerrado."],["En una banda de M\xF6bius, \xBFqu\xE9 ocurre con una orientaci\xF3n local de la superficie si la transportas a lo largo de la l\xEDnea central durante una vuelta completa?","La orientaci\xF3n regresa invertida","La longitud de la l\xEDnea cambia","La l\xEDnea deja de ser cerrada","La orientaci\xF3n gira dos vueltas completas y queda igual","El recorrido central atraviesa una identificaci\xF3n con media vuelta. Eso impide orientar toda la superficie de manera coherente."]],["hilbert-hotel","El hotel de Hilbert",["\xBFC\xF3mo admite un hu\xE9sped m\xE1s un hotel infinito lleno con habitaciones numeradas desde 1?","Mueve al hu\xE9sped de n a n + 1","Mueve al hu\xE9sped de n a n \u2212 1","Mueve a todos a la habitaci\xF3n 1","Cierra todas las habitaciones pares","El traslado deja libre la habitaci\xF3n 1 y cada hu\xE9sped conserva una habitaci\xF3n propia."],["En el hotel de Hilbert, todas las habitaciones numeradas 1, 2, 3, \u2026 est\xE1n ocupadas. Si n es el n\xFAmero de habitaci\xF3n actual de un hu\xE9sped, \xBFqu\xE9 traslado deja libres infinitas habitaciones sin desalojar a nadie?","Pasar de n a 2n","Pasar de n a n + 100","Intercambiar las habitaciones 1 y 2","Pasar de n a n + 1","Los hu\xE9spedes originales ocupan las habitaciones pares y las impares quedan disponibles."],["En el hotel de Hilbert, las habitaciones se numeran con los naturales. \xBFPor qu\xE9, incluso con el hotel vac\xEDo, resulta imposible asignar una habitaci\xF3n distinta a cada n\xFAmero real entre 0 y 1?","No se puede inyectar ese intervalo en los naturales","Los reales entre 0 y 1 son finitos","Los n\xFAmeros naturales no tienen subconjuntos infinitos","Una enumeraci\xF3n s\xED existe si se omiten los extremos","Los reales de cualquier intervalo no degenerado son no numerables."]],["euler-polyhedron-formula","La f\xF3rmula de Euler para poliedros",["\xBFQu\xE9 cantidades relaciona la f\xF3rmula cl\xE1sica de Euler para poliedros convexos?","V\xE9rtices, aristas y caras","\xC1ngulos, \xE1reas y vol\xFAmenes","Radios, di\xE1metros y cuerdas","Longitudes, alturas y apotemas","La relaci\xF3n es V \u2212 A + C = 2."],["Si V es el n\xFAmero de v\xE9rtices, A el de aristas y C el de caras de un cubo, \xBFcu\xE1nto vale V \u2212 A + C?","2","0","6","8","El cubo tiene 8 v\xE9rtices, 12 aristas y 6 caras."],["Si trazas una diagonal en una cara cuadrada de un cubo, \xBFqu\xE9 cambia en su caracter\xEDstica de Euler?","Nada, porque se a\xF1aden una arista y una cara","Aumenta uno, porque solo cambia el n\xFAmero de caras","Disminuye uno, porque solo cambia el n\xFAmero de aristas","Se duplica al triangular la cara","La diagonal divide una cara en dos y no a\xF1ade v\xE9rtices. Los dos cambios se cancelan."]]],["Curvas y astronom\xEDa",["kepler-orbits","Las \xF3rbitas de Kepler",["Seg\xFAn la primera ley de Kepler, \xBFd\xF3nde se encuentra el Sol en la \xF3rbita el\xEDptica ideal de un planeta?","En uno de sus focos","En el centro de la elipse","En el v\xE9rtice m\xE1s cercano","En el punto medio del semieje menor","En una elipse que no sea un c\xEDrculo, los focos est\xE1n desplazados respecto al centro."],["Seg\xFAn la segunda ley de Kepler, cuando un planeta recorre su \xF3rbita en dos intervalos de igual duraci\xF3n, \xBFqu\xE9 magnitud es igual en ambos intervalos?","El \xE1rea barrida por el segmento que une el Sol y el planeta","La longitud recorrida por el planeta","La distancia del planeta al Sol","El \xE1ngulo girado respecto al Sol","El \xE1rea barrida aumenta a ritmo constante, aunque var\xEDen la distancia al Sol y la velocidad."],["Seg\xFAn la tercera ley de Kepler, para planetas que orbitan el mismo cuerpo central y tienen masas despreciables frente a la suya, \xBFc\xF3mo se relacionan el periodo orbital T y el tama\xF1o de la \xF3rbita?","T\xB2 es proporcional al cubo del semieje mayor","T es proporcional al cuadrado de la excentricidad","T\xB2 es proporcional al cubo del semieje menor","T no depende del tama\xF1o de la \xF3rbita","En el modelo de Kepler, la escala del periodo la fija el semieje mayor."]],["hilbert-curve","La curva de Hilbert",["\xBFQu\xE9 regi\xF3n llena la curva de Hilbert en el l\xEDmite?","Un cuadrado","Solo el borde de un cuadrado","Un segmento horizontal","Una esfera","La curva l\xEDmite recorre todos los puntos del cuadrado."],["Al construir las aproximaciones sucesivas a la curva de Hilbert que llena un cuadrado, \xBFqu\xE9 patr\xF3n se usa para pasar de una etapa a la siguiente?","Copias orientadas y conectadas en cuatro subcuadrados","Un anillo de tri\xE1ngulos equil\xE1teros","C\xEDrculos conc\xE9ntricos sin conexi\xF3n","Un segmento que se acorta sin cambiar de direcci\xF3n","La orientaci\xF3n de las copias permite que el recorrido pase de un subcuadrado a otro."],["\xBFQu\xE9 propiedad tiene la funci\xF3n que parametriza la curva de Hilbert desde el intervalo [0, 1] hasta el cuadrado unidad?","Es continua y sobreyectiva sobre el cuadrado","Es un isomorfismo lineal entre el intervalo y el cuadrado","Deja fuera todo punto con coordenadas irracionales","Es inyectiva y su imagen es todo el cuadrado","Cada punto tiene al menos un par\xE1metro. Una biyecci\xF3n continua har\xEDa homeomorfos el intervalo compacto y el cuadrado."]]],["Estad\xEDstica",["central-limit-theorem","El teorema central del l\xEDmite",["Seg\xFAn el teorema central del l\xEDmite cl\xE1sico, \xBFa qu\xE9 distribuci\xF3n se acerca la de la suma de observaciones independientes e id\xE9nticamente distribuidas, de varianza finita y positiva, tras centrarla y escalarla?","La de una distribuci\xF3n normal","La de una distribuci\xF3n uniforme","La de una distribuci\xF3n siempre bimodal","La de un \xFAnico valor con probabilidad uno","La suma, tras centrarla y escalarla, adquiere una distribuci\xF3n que se acerca a la normal."],["\xBFA cu\xE1l de las siguientes cantidades se aplica el teorema central del l\xEDmite cl\xE1sico cuando aumenta el n\xFAmero de observaciones?","La suma estandarizada de observaciones independientes e id\xE9nticamente distribuidas con varianza finita positiva","Cada observaci\xF3n individual al repetir el muestreo","El m\xE1ximo de cualquier conjunto de observaciones","Cualquier suma sin hip\xF3tesis sobre la dependencia","La propiedad describe el comportamiento de la suma, incluso si cada observaci\xF3n tiene una distribuci\xF3n muy distinta de la normal."],["En una muestra de observaciones independientes de la misma poblaci\xF3n, con varianza finita y positiva, \xBFqu\xE9 le ocurre a la desviaci\xF3n t\xEDpica de la media muestral si el tama\xF1o de la muestra se cuadruplica?","Se reduce a la mitad","Se reduce a la cuarta parte","Se duplica","Se mantiene","La varianza de la media es la varianza individual dividida por el tama\xF1o muestral. Su ra\xEDz disminuye con la ra\xEDz del tama\xF1o."]],["projection-least-squares","Proyecci\xF3n y m\xEDnimos cuadrados",["\xBFQu\xE9 se minimiza en un ajuste ordinario por m\xEDnimos cuadrados?","La suma de los cuadrados de los residuos","La suma de los valores ajustados","El mayor residuo en valor absoluto","La suma de las distancias horizontales","Cada residuo mide la diferencia entre el valor observado y el estimado."],["\xBFQu\xE9 representa geom\xE9tricamente el vector ajustado de m\xEDnimos cuadrados?","La proyecci\xF3n ortogonal de las observaciones sobre el espacio de columnas","Una rotaci\xF3n de las observaciones","El complemento ortogonal del espacio de columnas","La proyecci\xF3n de los coeficientes sobre la recta de pendiente uno","En el espacio de columnas se encuentran todos los vectores de predicciones posibles."],["En un ajuste lineal por m\xEDnimos cuadrados ordinarios cuyo modelo incluye un t\xE9rmino constante, \xBFqu\xE9 propiedad cumple el conjunto de residuos?","Suman cero","Son todos positivos","Son todos iguales","Tienen varianza uno","El vector de residuos es perpendicular a cada columna. Su producto escalar con el vector de unos es su suma."]]],["Trigonometr\xEDa",["radians","Radianes",["\xBFQu\xE9 cociente mide un \xE1ngulo en radianes?","Longitud del arco dividida por el radio","Radio dividido por la longitud del arco","\xC1rea del c\xEDrculo dividida por su radio","Longitud del arco dividida por el di\xE1metro","El cociente compara el arco con el radio del mismo c\xEDrculo."],["\xBFPor qu\xE9 una vuelta completa mide 2\u03C0 radianes?","La circunferencia mide 2\u03C0 veces su radio","El di\xE1metro mide 2\u03C0 veces el radio","El \xE1rea del c\xEDrculo mide 2\u03C0 veces el radio","El radio mide la mitad de \u03C0 unidades","Al dividir la longitud de toda la circunferencia por su radio, queda 2\u03C0."],["Si duplicas el radio de un c\xEDrculo y mantienes fijo un \xE1ngulo central distinto de cero, \xBFc\xF3mo cambia la longitud del arco que abarca ese \xE1ngulo?","Duplica su longitud","Conserva su longitud","Se reduce a la mitad","Cuadruplica su longitud","Con \xE1ngulo fijo en radianes, la longitud de arco es proporcional al radio."]],["spherical-trigonometry","Trigonometr\xEDa esf\xE9rica",["\xBFSobre qu\xE9 curvas se trazan los lados de un tri\xE1ngulo esf\xE9rico?","C\xEDrculos m\xE1ximos","Cualquier paralelo","Espirales de la esfera","Rectas que atraviesan el centro","Un c\xEDrculo m\xE1ximo resulta de cortar la esfera con un plano que pasa por su centro."],["\xBFPuede un tri\xE1ngulo esf\xE9rico tener tres \xE1ngulos rectos?","S\xED, por ejemplo entre el polo y dos puntos del ecuador separados 90\xB0","No, porque los \xE1ngulos siempre suman 180\xB0","Solo si sus tres v\xE9rtices est\xE1n en el ecuador","Solo si el radio es infinito","Los dos meridianos cortan al ecuador en \xE1ngulo recto y se encuentran en el polo con el \xE1ngulo entre sus longitudes."],["\xBFQu\xE9 determina el exceso angular de un tri\xE1ngulo esf\xE9rico de radio fijo?","Su \xE1rea","El per\xEDmetro exacto","La longitud de cada lado por separado","La latitud de su centro","El \xE1rea es el exceso sobre \u03C0, medido en radianes, multiplicado por el cuadrado del radio."]]],["Grafos",["euler-hamilton","Caminos de Euler y Hamilton",["\xBFPor qu\xE9 elementos pasa exactamente una vez un camino euleriano?","Por todas las aristas","Por todos los v\xE9rtices","Por todos los ciclos","Por todos los pares de v\xE9rtices","Euler se refiere a recorrer conexiones. Un v\xE9rtice puede visitarse varias veces."],["\xBFQu\xE9 debe visitar exactamente una vez un camino hamiltoniano?","Cada v\xE9rtice","Cada arista","Cada cara de un dibujo plano","Cada ciclo del grafo","Hamilton se refiere a los v\xE9rtices y puede dejar aristas sin usar."],["Un grafo finito, conexo y no dirigido tiene exactamente dos v\xE9rtices de grado impar. \xBFQu\xE9 recorrido euleriano admite?","Un camino abierto entre esos dos v\xE9rtices","Un circuito que empieza y termina en el mismo v\xE9rtice impar","Un camino abierto entre dos v\xE9rtices pares","Ning\xFAn camino que use todas las aristas","En los v\xE9rtices intermedios se emparejan entradas con salidas. Los dos impares deben ser los extremos."]]],["Conjeturas e historia",["goldbach","La conjetura de Goldbach",["\xBFQu\xE9 afirma la versi\xF3n fuerte de la conjetura de Goldbach?","Cada entero par mayor que dos es suma de dos primos","Cada impar es producto de dos primos","Cada primo es suma de dos enteros pares","Cada cuadrado es suma de dos primos distintos","Los dos primos pueden coincidir. Por ejemplo, 4 = 2 + 2."],["En el contexto de la conjetura fuerte de Goldbach, si un entero par mayor que cuatro se expresa como suma de dos primos, \xBFqu\xE9 se puede afirmar sobre la paridad de esos primos?","Ambos son impares","Uno es necesariamente dos","Ambos son pares","Son necesariamente distintos","Dos es el \xFAnico primo par. Si aparece en una suma par, el otro tambi\xE9n debe ser dos."],["Si se comprueba la conjetura fuerte de Goldbach para todos los enteros pares desde 4 hasta una cota finita, \xBFqu\xE9 garantiza esa comprobaci\xF3n?","Que ning\xFAn contraejemplo est\xE1 dentro del rango verificado","Que vale para todos los pares por inducci\xF3n","Que solo podr\xEDa fallar para los impares","Que cada par verificado tiene una \xFAnica representaci\xF3n","Una verificaci\xF3n finita descarta contraejemplos en ese rango. Hace falta un argumento general para cubrir el resto."]],["gauss-school-sum","La suma escolar de Gauss",["\xBFQu\xE9 idea ilustra la an\xE9cdota de la suma escolar de Gauss?","Emparejar t\xE9rminos de extremos opuestos","Sumar primero solo los primos","Multiplicar t\xE9rminos consecutivos","Sustituir todos los t\xE9rminos por el menor","El primero y el \xFAltimo suman lo mismo que el segundo y el pen\xFAltimo."],["En el m\xE9todo de la suma de Gauss se emparejan los t\xE9rminos de extremos opuestos. \xBFQu\xE9 propiedad de una progresi\xF3n aritm\xE9tica garantiza que todas esas parejas suman lo mismo?","La diferencia entre t\xE9rminos consecutivos es constante","Todos los t\xE9rminos son positivos","El n\xFAmero de t\xE9rminos es par","El primer t\xE9rmino vale uno","Al avanzar un paso desde un extremo y retroceder otro desde el otro, los cambios se cancelan."],["Para hallar la suma de una progresi\xF3n aritm\xE9tica con un n\xFAmero impar de t\xE9rminos, se escribe la progresi\xF3n dos veces, una en orden directo y otra en orden inverso, y se suman los t\xE9rminos por columnas. \xBFQu\xE9 ocurre con el t\xE9rmino central?","Aparece dos veces en la posici\xF3n central y suma lo mismo que cualquier pareja","Se elimina para que queden parejas","Se suma una sola vez porque coincide consigo mismo","Obliga a usar una f\xF3rmula distinta","La suma de ambas listas tiene dos copias del t\xE9rmino central. Al dividir el total entre dos, se recupera su aportaci\xF3n original."]]]],ne=oe.flatMap(([o,...s])=>s.flatMap(([e,a,...t])=>t.map(([c,b,m,f,P,h],p)=>({theme:o,route:"/articles/"+e,article:a,level:p,prompt:c,correct:b,options:[b,m,f,P],explanation:h})))),ie=[["Geometr\xEDa",K],["N\xFAmeros",Y],["\xC1lgebra y complejos",V],["An\xE1lisis",X],["Probabilidad y estad\xEDstica",J],["Grafos y combinatoria",$],["Sistemas din\xE1micos",W],["Fractales",Z]],re=ie.flatMap(([o,s])=>s.flatMap(([e,a,t,...c])=>{let b=c.map(([f])=>f),m=[0,1,2,t];return c.map(([f,P,h],p)=>({theme:o,article:a,route:"/articles/"+e,level:m[p],prompt:P,correct:f,options:b,explanation:h}))})),A=[...ne,...re];var se=(o,s)=>s.id,T=(o,s)=>s.prompt,te=o=>[o];function le(o,s){if(o&1&&(i(0,"small"),r(1),n()),o&2){let e=d().$implicit,a=d(2);l(),v("R\xE9cord de ",a.records[e.id]," puntos")}}fu